window.SENTENCE_CORPUS = [{"lesson":1,"key":"1","review":false,"title":"September is the best time to visit Beijing","titleCn":"九月去北京旅游最好","points":[{"id":"1-g1","no":1,"cn":"助动词“要”","en":"The Auxiliary Verb 要","note":"要 is an auxiliary verb: 要+V expresses a plan or intention; the negative is 不想/不要 + V.","subs":[{"id":"a","label":"要 + V","exp":"Expresses intention or a plan."},{"id":"b","label":"不 + 要 + V","exp":"Negates a plan (\"not going to\")."}],"items":[{"c":"我（不）要去商店。","en":"I am (not) going to the store.","sub":"a","lv":1},{"c":"明天我要去北京。","en":"I am going to Beijing tomorrow.","sub":"a","lv":1},{"c":"我不要去商店。","en":"I am not going to the store.","sub":"b","lv":1},{"c":"我们要不要去买新的电脑？","en":"Shall we buy a new computer?","sub":"a","lv":2},{"c":"我们要不要去澳大利亚？","en":"Shall we go to Australia?","sub":"a","lv":1},{"c":"我们要不要去公园陪妹妹玩？","en":"Shall we go to the park to play with our little sister?","sub":"a","lv":1},{"c":"我们去哪儿？去公园，超市，还是商场？","en":"Where shall we go — the park, the supermarket, or the mall?","sub":"a","lv":1},{"c":"我不要吃这个。","en":"I don't want to eat this.","sub":"b","lv":2},{"c":"他不要来。","en":"He isn't going to come.","sub":"b","lv":1},{"c":"我们不要买。","en":"We aren't going to buy it.","sub":"b","lv":1},{"c":"我不要去那儿。","en":"I'm not going there.","sub":"b","lv":1},{"c":"妈妈要我去买水果。","en":"Mum wants me to go and buy fruit.","sub":"a","lv":1},{"c":"老师要我们明天早点儿来。","en":"The teacher wants us to come a bit earlier tomorrow.","sub":"a","lv":1},{"c":"我不要买这个手机。","en":"I don't want to buy this phone.","sub":"b","lv":2},{"c":"他不要吃我做的饭。","en":"He doesn't want to eat the food I make.","sub":"b","lv":2},{"c":"妈妈不要我去老师推荐的那个地方。","en":"Mum doesn't want me to go to the place the teacher recommended.","sub":"b","lv":3},{"c":"我们要买两本书。","en":"We want to buy two books.","sub":"a","lv":2},{"c":"我们要去老师推荐的那个饭馆。","en":"We want to go to the restaurant the teacher recommended.","sub":"a","lv":3},{"c":"我们要去买老师推荐的那本书。","en":"We want to go buy that book the teacher recommended.","sub":"a","lv":3},{"c":"我不要吃妈妈做的这个菜。","en":"I don't want to eat this dish Mum made.","sub":"b","lv":3},{"c":"因为那家饭馆很有名，我们明天要去。","en":"We're going tomorrow because that restaurant is very famous.","sub":"a","lv":3},{"c":"我们要在他说的那个地方见面。","en":"We'll meet at the place he mentioned.","sub":"a","lv":3},{"c":"因为下雨了，我们不要去老师说的那个公园了。","en":"Let's not go to the park the teacher mentioned, since it's raining.","sub":"a","lv":3}]},{"id":"1-g2","no":2,"cn":"程度副词“最”","en":"The Adverb of Degree 最","note":"最 is an adverb of degree meaning \"the most\". It comes before the adjective and takes no 很.","subs":[{"id":"a","label":"最 + adj","exp":"Marks the highest degree."},{"id":"b","label":"最 + adj + 的 + N","exp":"As an attributive."}],"items":[{"c":"它的眼睛最漂亮。","en":"It has the prettiest eyes.","sub":"a","lv":2},{"c":"九月去北京旅游最好。","en":"September is the best time to visit Beijing.","sub":"a","lv":2},{"c":"这是我最喜欢的书。","en":"This is my favourite book.","sub":"b","lv":2},{"c":"这个房间最大。","en":"This room is the biggest.","sub":"a","lv":2},{"c":"他最忙。","en":"He is the busiest.","sub":"a","lv":1},{"c":"我最喜欢运动。","en":"I like exercise best.","sub":"a","lv":1},{"c":"他是我最好的朋友。","en":"He is my best friend.","sub":"b","lv":2},{"c":"这是最贵的手机。","en":"This is the most expensive phone.","sub":"b","lv":2},{"c":"那是最漂亮的房间。","en":"That is the prettiest room.","sub":"b","lv":2},{"c":"这是最好的工作。","en":"This is the best job.","sub":"b","lv":2},{"c":"这是最便宜的衣服。","en":"This is the cheapest piece of clothing.","sub":"b","lv":2},{"c":"这是我吃过的最好吃的菜。","en":"This is the most delicious dish I've ever had.","sub":"b","lv":2},{"c":"你买的那个是不是最便宜的？","en":"Is the one you bought the cheapest?","sub":"a","lv":3},{"c":"这个手机最便宜。","en":"This phone is the cheapest.","sub":"a","lv":2},{"c":"你买的那件最贵。","en":"The one you bought is the most expensive.","sub":"a","lv":3},{"c":"那个商店的东西最贵。","en":"The things in that shop are the most expensive.","sub":"b","lv":2},{"c":"这是我妈妈做的最好吃的饺子。","en":"These are the most delicious dumplings my mum makes.","sub":"b","lv":2},{"c":"这是我买的最便宜的那个手机。","en":"This is the cheapest phone I bought.","sub":"b","lv":3},{"c":"这是他推荐的最好吃的那家饭馆。","en":"This is the most delicious restaurant he recommended.","sub":"b","lv":3}]},{"id":"1-g3","no":3,"cn":"概数的表达：几、多","en":"Approximate Numbers: 几 and 多","note":"几 and 多 both give an approximate number. With 个/本/件/次, 多 must come BEFORE the measure word; with 年/月/星期/岁/块 it can come before or after; 度 only takes 多 before, 点 only after.","subs":[{"id":"a","label":"几 / 十几 / 几十 + M + N","exp":"Approximate number with 几."},{"id":"b","label":"Number + 多 + M","exp":"个/本/件/次 — 多 must come BEFORE the measure word."},{"id":"c","label":"Number + M + 多","exp":"年/月/星期/点/岁/块 — 多 AFTER the measure word."},{"id":"d","label":"Number + 多 + M","exp":"年/月/星期/岁/块/度 — 多 BEFORE also works; 点 never does."},{"id":"e","label":"Number + 几 + M","exp":"二十几/三十几 — 几 follows a round number instead of standing alone."},{"id":"f","label":"Number + M + 几","exp":"一米八几 / 三点几 — 几 AFTER a round number + measure word (a little over)."}],"items":[{"c":"我们要不要买十几把椅子？","en":"Shall we buy a dozen or so chairs?","sub":"a","lv":2},{"c":"十多个人。","en":"More than ten people.","sub":"b","lv":2},{"c":"一百多本书。","en":"More than a hundred books.","sub":"b","lv":2},{"c":"一千多件衣服。","en":"More than a thousand items of clothing.","sub":"b","lv":2},{"c":"三十多次。","en":"More than thirty times.","sub":"b","lv":2},{"c":"我在中国六个多月了。","en":"I have been in China for more than six months.","sub":"c","lv":2},{"c":"三点多。","en":"A bit past three.","sub":"c","lv":2},{"c":"这个杯子二十多块钱。","en":"This cup costs over twenty yuan.","sub":"c","lv":2},{"c":"他三十多岁。","en":"He is over thirty.","sub":"d","lv":2},{"c":"十多个月。","en":"More than ten months.","sub":"d","lv":2},{"c":"现在外面二十多度。","en":"It's over twenty degrees outside now.","sub":"d","lv":2},{"c":"三十多度的时候特别热。","en":"When it's over thirty degrees it's really hot.","sub":"d","lv":3},{"c":"我的眼镜两百多度。","en":"My glasses are over two hundred degrees (short-sighted).","sub":"d","lv":2},{"c":"现在外面二十几度。","en":"It's twenty-something degrees outside now.","sub":"e","lv":2},{"c":"我们班有三十几个人。","en":"There are thirty-something people in our class.","sub":"e","lv":2},{"c":"他一米八几。","en":"He's a little over 1.8 metres tall.","sub":"f","lv":2},{"c":"现在三点几了。","en":"It's a bit past three now.","sub":"f","lv":2},{"c":"我有几本书。","en":"I have a few books.","sub":"a","lv":2},{"c":"他买了十几个苹果。","en":"He bought a dozen or so apples.","sub":"a","lv":2},{"c":"教室里有几十个人。","en":"There are dozens of people in the classroom.","sub":"a","lv":2},{"c":"我要买几件衣服。","en":"I want to buy a few pieces of clothing.","sub":"a","lv":2},{"c":"二十多块钱。","en":"More than twenty yuan.","sub":"b","lv":2},{"c":"我等他两个多小时。","en":"I waited for him for over two hours.","sub":"c","lv":2},{"c":"现在十点多。","en":"It's a bit past ten now.","sub":"c","lv":2},{"c":"十几块钱。","en":"A dozen or so yuan.","sub":"e","lv":2},{"c":"二十几本书。","en":"Twenty-something books.","sub":"e","lv":2},{"c":"三十几件衣服。","en":"Thirty-something items of clothing.","sub":"e","lv":2},{"c":"两米几。","en":"A little over two metres.","sub":"f","lv":2},{"c":"他有一米九几。","en":"He is just over 1.9 metres.","sub":"f","lv":2},{"c":"现在四点几。","en":"It's just after four.","sub":"f","lv":2},{"c":"我三点多到。","en":"I arrive a bit after three.","sub":"c","lv":2},{"c":"我三十多岁的时候去过很多国家。","en":"When I was in my thirties I visited many countries.","sub":"d","lv":3},{"c":"我们有几十个学生。","en":"We have several dozen students.","sub":"a","lv":2},{"c":"他买了三十多件衣服。","en":"He bought more than thirty pieces of clothing.","sub":"b","lv":2},{"c":"我等了三个多小时。","en":"I waited more than three hours.","sub":"c","lv":2},{"c":"这个学校的学生有五百多个。","en":"This school has more than five hundred students.","sub":"d","lv":2},{"c":"我爸爸四十多岁的时候开始学汉语。","en":"My dad started learning Chinese when he was in his forties.","sub":"d","lv":3},{"c":"他买了三十几本书。","en":"He bought thirty-some books.","sub":"e","lv":2},{"c":"他身高一米七几。","en":"He is just over 1.7 metres tall.","sub":"f","lv":2}]},{"id":"1-g4","no":4,"cn":"副词“也”","en":"The Adverb 也","tag":"extended","tags":["TEXT"],"note":"也 means \"also / too\" and sits after the subject, before the verb or adjective. In one predicate, 不A也不B means \"neither A nor B\". A，也不A lets the same subject both affirm and deny the same thing (\"sort of / not really\").","subs":[{"id":"a","label":"Subject + 也 + V / Adj","exp":"也 = also / too, after the subject."},{"id":"b","label":"不A也不B","exp":"也 doubled in one predicate: neither A nor B."},{"id":"c","label":"Short answer: 我也是","exp":"Agreeing with someone in one short clause."},{"id":"d","label":"A，也不A","exp":"Same subject both affirms and denies the same thing — \"sort of / not really\"."}],"items":[{"c":"我也要去北京。","en":"I'm going to Beijing too.","sub":"a","lv":1},{"c":"他也会说汉语。","en":"He can speak Chinese too.","sub":"a","lv":1},{"c":"我喜欢喝茶，我妹妹也喜欢喝茶。","en":"I like tea, and my little sister likes tea too.","sub":"a","lv":1},{"c":"这个杯子很便宜，那个杯子也很便宜。","en":"This cup is cheap, and that one is cheap too.","sub":"a","lv":2},{"c":"他不想去，我也不想去。","en":"He doesn't want to go, and neither do I.","sub":"a","lv":1},{"c":"九月的北京天气不冷也不热。","en":"In September the weather in Beijing is neither cold nor hot.","sub":"b","lv":2},{"c":"这个椅子不大也不小。","en":"This chair is neither too big nor too small.","sub":"b","lv":2},{"c":"他是老师，我也是。","en":"He is a teacher, and so am I.","sub":"c","lv":1},{"c":"这个好看，也不好看。","en":"It's pretty, but not really.","sub":"d","lv":2},{"c":"这杯咖啡苦，也不苦。","en":"It's bitter, but not really.","sub":"d","lv":2},{"c":"那个地方远，也不远。","en":"It's far, but not really.","sub":"d","lv":2},{"c":"这件衣服不贵也不便宜。","en":"This clothing is neither expensive nor cheap.","sub":"b","lv":2},{"c":"他不高也不矮。","en":"He is neither tall nor short.","sub":"b","lv":1},{"c":"这个房间不干净也不脏。","en":"This room is neither clean nor dirty.","sub":"b","lv":2},{"c":"他要去北京，我也是。","en":"He's going to Beijing, and so am I.","sub":"c","lv":1},{"c":"她喜欢运动，我也是。","en":"She likes exercise, and so do I.","sub":"c","lv":1},{"c":"他累了，我也是。","en":"He's tired, and so am I.","sub":"c","lv":1},{"c":"他很忙，我也是。","en":"He's busy, and so am I.","sub":"c","lv":2},{"c":"这个贵，也不贵。","en":"It's expensive, but not really.","sub":"d","lv":2},{"c":"今天冷，也不冷。","en":"It's cold, but not really.","sub":"d","lv":1},{"c":"昨天买的衣服，我也想买。","en":"I also want to buy the clothing that was bought yesterday.","sub":"a","lv":2},{"c":"我买的东西他也不喜欢。","en":"He doesn't like the things I bought either.","sub":"a","lv":2},{"c":"他买的衣服好看，也不好看。","en":"The clothes he bought are kind of nice, but not really.","sub":"d","lv":2},{"c":"我朋友也喜欢这个电影。","en":"My friend also likes this movie.","sub":"a","lv":2},{"c":"你买的那本书我也看过。","en":"I've also read the book you bought.","sub":"a","lv":3},{"c":"这个手机不贵也不便宜。","en":"This phone is neither expensive nor cheap.","sub":"b","lv":2},{"c":"你买的那个不贵也不便宜。","en":"The one you bought is neither expensive nor cheap.","sub":"b","lv":3},{"c":"妈妈做的菜不咸也不淡。","en":"The food my mum makes is neither salty nor bland.","sub":"b","lv":2},{"c":"他喜欢这个电影，我也是。","en":"He likes this movie; me too.","sub":"c","lv":2},{"c":"这个手机贵，也不贵。","en":"This phone is expensive — well, not really.","sub":"d","lv":2},{"c":"你买的衣服贵，也不贵。","en":"The clothes you bought are expensive — well, not really.","sub":"d","lv":2},{"c":"你买的这个手机不贵也不便宜。","en":"This phone you bought is neither expensive nor cheap.","sub":"b","lv":3},{"c":"你买的这个手机贵，也不贵。","en":"This phone you bought is expensive — well, not really.","sub":"d","lv":3},{"c":"他推荐的那个饭馆远，也不远。","en":"That restaurant he recommended is far — well, not really.","sub":"d","lv":3},{"c":"他推荐的那本书我也想买。","en":"I also want to buy that book he recommended.","sub":"a","lv":3}]}]},{"lesson":2,"key":"2","review":false,"title":"I get up at six every day","titleCn":"我每天六点起床","points":[{"id":"2-g1","no":1,"cn":"问句：“是不是”与正反问","en":"The 是不是 Question & Affirmative-Negative Questions","note":"A statement can become a question with the tag 是不是, or by repeating the predicate in the affirmative and negative (A不A).","subs":[{"id":"a","label":"是不是 + predicate？","exp":"Tag question with 是不是."},{"id":"b","label":"statement，是不是？","exp":"是不是 at the end."},{"id":"c","label":"V + 不 + V + (O)？","exp":"Affirmative-negative: verb repeated."},{"id":"d","label":"adj + 不 + adj？","exp":"Affirmative-negative: adjective repeated."},{"id":"e","label":"V + O + 不 + V？","exp":"The object splits the verb pair."}],"items":[{"c":"你是不是中国人？","en":"Are you Chinese?","sub":"a","lv":1},{"c":"你很少生病，是不是喜欢运动？","en":"You seldom get sick — do you like sports?","sub":"a","lv":2},{"c":"你是中国人，是不是？","en":"You are Chinese, aren't you?","sub":"b","lv":1},{"c":"今天去不去打球？","en":"Are we going to play ball today or not?","sub":"c","lv":1},{"c":"你想不想去超市？","en":"Do you want to go to the supermarket or not?","sub":"c","lv":1},{"c":"你们今天高兴不高兴？","en":"Are you happy today or not?","sub":"d","lv":1},{"c":"你想去超市不想？","en":"Do you want to go to the supermarket or not?","sub":"e","lv":1},{"c":"你是不是学生？","en":"Are you a student?","sub":"a","lv":1},{"c":"他是不是你的朋友？","en":"Is he your friend?","sub":"a","lv":2},{"c":"明天是不是星期天？","en":"Is tomorrow Sunday?","sub":"a","lv":1},{"c":"你是老师，是不是？","en":"You're a teacher, aren't you?","sub":"b","lv":1},{"c":"你喜欢喝茶，是不是？","en":"You like drinking tea, don't you?","sub":"b","lv":1},{"c":"他去过北京，是不是？","en":"He's been to Beijing, hasn't he?","sub":"b","lv":1},{"c":"今天很冷，是不是？","en":"It's cold today, isn't it?","sub":"b","lv":2},{"c":"你吃不吃苹果？","en":"Do you eat apples or not?","sub":"c","lv":1},{"c":"你喜不喜欢看电影？","en":"Do you like watching movies?","sub":"c","lv":1},{"c":"他来不来？","en":"Is he coming?","sub":"c","lv":1},{"c":"这个苹果甜不甜？","en":"Is this apple sweet?","sub":"d","lv":2},{"c":"你的房间大不大？","en":"Is your room big?","sub":"d","lv":2},{"c":"今天的天气好不好？","en":"Is the weather good today?","sub":"d","lv":2},{"c":"这件衣服贵不贵？","en":"Is this piece of clothing expensive?","sub":"d","lv":2},{"c":"你吃饭不吃？","en":"Will you eat or not?","sub":"e","lv":1},{"c":"你去学校不去？","en":"Will you go to school or not?","sub":"e","lv":1},{"c":"你买这本书不买？","en":"Will you buy this book?","sub":"e","lv":2},{"c":"他回家不回？","en":"Is he going home?","sub":"e","lv":1},{"c":"老师是不是让你明天来？","en":"Did the teacher ask you to come tomorrow?","sub":"a","lv":2},{"c":"你买的书是不是这本？","en":"Is the book you bought this one?","sub":"a","lv":3},{"c":"这个房间是不是他的？","en":"Is this room his?","sub":"a","lv":2},{"c":"你昨天买的手机是不是这个？","en":"Is the phone you bought yesterday this one?","sub":"a","lv":3},{"c":"你喜欢这本书，是不是？","en":"You like this book, right?","sub":"b","lv":2},{"c":"你买的那个很贵，是不是？","en":"The one you bought is very expensive, right?","sub":"b","lv":3},{"c":"他做的菜很好吃，是不是？","en":"The food he makes is delicious, right?","sub":"b","lv":3},{"c":"你吃不吃这个苹果？","en":"Are you going to eat this apple?","sub":"c","lv":2},{"c":"你买不买那件衣服？","en":"Are you going to buy that piece of clothing?","sub":"c","lv":2},{"c":"你买的那个苹果甜不甜？","en":"Is the apple you bought sweet?","sub":"c","lv":3},{"c":"他做的菜好不好吃？","en":"Is the food he makes tasty?","sub":"c","lv":2},{"c":"这个苹果大不大？","en":"Is this apple big?","sub":"d","lv":2},{"c":"你买的那件衣服贵不贵？","en":"Is the piece of clothing you bought expensive?","sub":"d","lv":3},{"c":"他说的那个地方远不远？","en":"Is the place he mentioned far?","sub":"d","lv":3},{"c":"你喝这个茶不喝？","en":"Are you going to drink this tea?","sub":"e","lv":2},{"c":"你吃我做的饭不吃？","en":"Are you going to eat the food I make?","sub":"e","lv":2},{"c":"你看他买的书不看？","en":"Are you going to read the book he bought?","sub":"e","lv":2},{"c":"你买不买老师推荐的那本书？","en":"Are you going to buy that book the teacher recommended?","sub":"c","lv":3},{"c":"你吃我做的这个菜不吃？","en":"Are you going to eat this dish I made?","sub":"e","lv":3},{"c":"你看他推荐的那本书不看？","en":"Are you going to read that book he recommended?","sub":"e","lv":3},{"c":"因为下雨，我们不去那个很远的公园了，是不是？","en":"We're not going to that far-away park because it's raining, right?","sub":"b","lv":3},{"c":"他说的那个饭馆离这儿很近，是不是？","en":"The restaurant he mentioned is close to here, isn't it?","sub":"b","lv":3},{"c":"老师说的那个地方很远，是不是？","en":"The place the teacher mentioned is far away, isn't it?","sub":"b","lv":3}]},{"id":"2-g2","no":2,"cn":"代词“每”","en":"The Pronoun 每","note":"每 means \"every / each\". It must be followed by a measure word, and 都 often appears later in the sentence.","subs":[{"id":"a","label":"每 + M + N","exp":"\"Every\" + measure word."},{"id":"b","label":"每 + M + N + 都……","exp":"With 都 in the predicate."}],"items":[{"c":"我每个星期六十点起床。","en":"I get up at ten every Saturday.","sub":"a","lv":2},{"c":"我每天早上六点起床。","en":"I get up at six every morning.","sub":"a","lv":2},{"c":"他每天都运动。","en":"He exercises every day.","sub":"b","lv":1},{"c":"每个人都很忙。","en":"Everyone is busy.","sub":"a","lv":2},{"c":"每件衣服都很漂亮。","en":"Every piece of clothing is pretty.","sub":"a","lv":2},{"c":"每天早上都跑步。","en":"I run every morning.","sub":"b","lv":1},{"c":"每本书都很有意思。","en":"Every book is interesting.","sub":"a","lv":2},{"c":"每个房间都很干净。","en":"Every room is clean.","sub":"b","lv":1},{"c":"每门课都很有意思。","en":"Every class is interesting.","sub":"b","lv":2},{"c":"每个孩子都喜欢吃糖。","en":"Every child likes candy.","sub":"b","lv":1},{"c":"老师说的每句话我都记住了。","en":"I remembered every word the teacher said.","sub":"b","lv":2},{"c":"我每天吃的东西都很便宜。","en":"The things I eat every day are all cheap.","sub":"b","lv":3},{"c":"每个地方的东西都很好吃。","en":"The food in every place is delicious.","sub":"a","lv":2},{"c":"我买的每件衣服都很贵。","en":"Every piece of clothing I bought is expensive.","sub":"a","lv":3},{"c":"他做的每道菜都很好吃。","en":"Every dish he makes is delicious.","sub":"a","lv":3},{"c":"每个学生的问题都很多。","en":"Every student has a lot of questions.","sub":"b","lv":2},{"c":"老师说的每句话都很有用。","en":"Everything the teacher says is very useful.","sub":"b","lv":2},{"c":"老师说的每句话我都记在这个本子上。","en":"I've written down every word the teacher said in this notebook.","sub":"b","lv":3}]},{"id":"2-g3","no":3,"cn":"疑问代词“多”","en":"The Interrogative 多","note":"多 before an adjective asks \"how …?\" — used for age, height, size, distance, duration or price.","subs":[{"id":"a","label":"多 + adj？","exp":"Asks about degree, age, size, etc."},{"id":"b","label":"多大 / 多高 / 多远 / 多长时间","exp":"Common fixed questions."}],"items":[{"c":"它多大了？","en":"How old is it?","sub":"a","lv":1},{"c":"大卫今年多大？","en":"How old is David this year?","sub":"b","lv":1},{"c":"他多高？","en":"How tall is he?","sub":"b","lv":1},{"c":"公司离你家有多远？","en":"How far is the company from your home?","sub":"b","lv":2},{"c":"你在这儿工作多长时间了？","en":"How long have you worked here?","sub":"b","lv":2},{"c":"这个房间多大？","en":"How big is this room?","sub":"a","lv":2},{"c":"多少钱买的？","en":"How much did it cost?","sub":"b","lv":2},{"c":"你的孩子多大了？","en":"How old is your child?","sub":"a","lv":2},{"c":"那个楼多高？","en":"How tall is that building?","sub":"a","lv":2},{"c":"这个城市多大？","en":"How big is this city?","sub":"a","lv":2},{"c":"你买的房子多大？","en":"How big is the house you bought?","sub":"a","lv":2},{"c":"他住的那个房间多大？","en":"How big is the room he lives in?","sub":"a","lv":3},{"c":"那个城市的东西多贵？","en":"How expensive are things in that city?","sub":"a","lv":2},{"c":"你买的那个房子多大？","en":"How big is the flat you bought?","sub":"a","lv":3},{"c":"从这儿到那个公园多远？","en":"How far is it from here to that park?","sub":"b","lv":2},{"c":"你买的房子离公司多远？","en":"How far is the flat you bought from the office?","sub":"b","lv":3},{"c":"他说的那个公园离这儿多远？","en":"How far is the park he mentioned from here?","sub":"b","lv":3}]},{"id":"2-g4","no":4,"cn":"“连…也/都”表甚至","en":"连…也/都 for \"even\"","tag":"extended","tags":["TEXT"],"note":"连 X 也/都 Y stresses that even X (the least likely) does Y. In speech 连 can be dropped, leaving 也/都 alone to carry the \"even\" meaning.","subs":[{"id":"a","label":"连 + X + 也/都 + V","exp":"Full form: even X (does V) — 连 can pair with 也 or 都."},{"id":"b","label":"（连）X + 也 + V","exp":"连 dropped in speech; 也 alone still means \"even\"."}],"items":[{"c":"他连早饭也没吃。","en":"He didn't even eat breakfast.","sub":"a","lv":1},{"c":"连小孩子也知道。","en":"Even little kids know that.","sub":"a","lv":1},{"c":"他连一个朋友也没有。","en":"He doesn't have even one friend.","sub":"a","lv":2},{"c":"张老师星期六也不休息。","en":"Mr Zhang doesn't even rest on Saturday.","sub":"b","lv":1},{"c":"他连饭也没吃就走了。","en":"He left without even eating.","sub":"a","lv":1},{"c":"我连他的名字都不知道。","en":"I don't even know his name.","sub":"a","lv":2},{"c":"他一个字也不认识。","en":"He doesn't recognize a single character.","sub":"b","lv":2},{"c":"我一点儿也不知道。","en":"I don't know anything at all.","sub":"b","lv":2},{"c":"他一分钱也没有。","en":"He doesn't have a penny.","sub":"b","lv":1},{"c":"她一句话也不说。","en":"She doesn't say a word.","sub":"b","lv":2},{"c":"他连我买的礼物也没看。","en":"He didn't even look at the present I bought.","sub":"a","lv":2},{"c":"连老师说的话他也不听。","en":"He doesn't even listen to what the teacher says.","sub":"a","lv":2},{"c":"他连这个字也不认识。","en":"He doesn't even know this character.","sub":"a","lv":2},{"c":"他连妈妈做的饭也不吃。","en":"He won't even eat the food Mum makes.","sub":"a","lv":2},{"c":"他这本书也没看过。","en":"He hasn't even read this book.","sub":"b","lv":2},{"c":"你买的那个东西他也没看过。","en":"He hasn't even seen the thing you bought.","sub":"b","lv":3},{"c":"老师说的话他一句也没记住。","en":"He didn't remember a single word the teacher said.","sub":"b","lv":3},{"c":"他连我买的这个礼物也没看。","en":"He didn't even look at this gift I bought.","sub":"a","lv":3},{"c":"他连妈妈做的这个菜也不吃。","en":"He won't even eat this dish Mum made.","sub":"a","lv":3}]}]},{"lesson":3,"key":"3","review":false,"title":"The red one on the left is mine","titleCn":"左边那个红色的是我的","points":[{"id":"3-g1","no":1,"cn":"“的”字短语","en":"The 的 Phrase","note":"The 的 phrase omits the noun after 的 when it is already known — 的 itself carries the meaning \"the one(s) that…\".","subs":[{"id":"a","label":"Phrase + 的","exp":"Standalone noun phrase."},{"id":"b","label":"Pronoun / adj / V + 的 + N","exp":"As an attributive."}],"items":[{"c":"这块手表是你昨天买的吗？","en":"Is this watch the one you bought yesterday?","sub":"a","lv":3},{"c":"左边那个红色的是我的。","en":"The red one on the left is mine.","sub":"a","lv":2},{"c":"这是新买的自行车。","en":"This is a newly bought bicycle.","sub":"b","lv":1},{"c":"这是谁的？","en":"Whose is this?","sub":"a","lv":1},{"c":"那个红色的很好看。","en":"The red one looks nice.","sub":"a","lv":2},{"c":"我的是新的。","en":"Mine is the new one.","sub":"a","lv":1},{"c":"红色的衣服很好看。","en":"The red clothing is nice.","sub":"b","lv":2},{"c":"我买的书在桌子上。","en":"The book I bought is on the table.","sub":"b","lv":3},{"c":"这是妈妈做的饭。","en":"This is the meal Mum made.","sub":"b","lv":2},{"c":"他穿的是新衣服。","en":"What he's wearing is new clothing.","sub":"b","lv":2},{"c":"这个手机是新的。","en":"This phone is a new one.","sub":"a","lv":2},{"c":"那个红色的书包是他买的。","en":"That red schoolbag is the one he bought.","sub":"a","lv":3},{"c":"这本书是新买的。","en":"This book is newly bought.","sub":"b","lv":2},{"c":"你说的那个饭馆很有名。","en":"That restaurant you mentioned is very famous.","sub":"b","lv":3}]},{"id":"3-g2","no":2,"cn":"“一下”","en":"The Expression 一下","note":"一下 softens a verb, making the action brief or tentative — \"a little / for a moment\".","subs":[{"id":"a","label":"V + 一下","exp":"Makes the action short and casual."},{"id":"b","label":"V + 一下 + N","exp":"With a short object."}],"items":[{"c":"我看一下。","en":"Let me take a look.","sub":"a","lv":1},{"c":"请等一下。","en":"Please wait a moment.","sub":"a","lv":1},{"c":"我介绍一下我的朋友。","en":"Let me introduce my friend.","sub":"b","lv":2},{"c":"休息一下。","en":"Rest a bit.","sub":"a","lv":1},{"c":"想一下。","en":"Think a moment.","sub":"a","lv":1},{"c":"看一下这本书。","en":"Take a look at this book.","sub":"b","lv":2},{"c":"你听一下。","en":"Listen for a moment.","sub":"a","lv":1},{"c":"你等一下我。","en":"Wait for me a moment.","sub":"b","lv":1},{"c":"我问一下老师。","en":"Let me ask the teacher.","sub":"b","lv":2},{"c":"我看一下手机。","en":"Let me check my phone.","sub":"b","lv":1},{"c":"你看一下我买的书。","en":"Take a look at the book I bought.","sub":"b","lv":2},{"c":"你听一下老师说的话。","en":"Listen to what the teacher said.","sub":"b","lv":2},{"c":"你试一下这个手机。","en":"Try this phone.","sub":"a","lv":2},{"c":"你尝一下这个菜。","en":"Taste this dish.","sub":"a","lv":2},{"c":"你试一下我买的手机。","en":"Try the phone I bought.","sub":"a","lv":2},{"c":"他听一下老师说的话就明白了。","en":"He understood as soon as he listened to what the teacher said.","sub":"a","lv":2},{"c":"我问一下这个老师。","en":"Let me ask this teacher.","sub":"b","lv":2},{"c":"你问一下他说的那个地方怎么走。","en":"Ask how to get to the place he mentioned.","sub":"b","lv":3},{"c":"你试一下我买的这个手机。","en":"Try this phone I bought.","sub":"a","lv":3},{"c":"你吃一下妈妈做的这个菜。","en":"Try this dish Mum made.","sub":"a","lv":3},{"c":"你听一下老师说的这几句话。","en":"Listen to these few sentences the teacher said.","sub":"b","lv":3}]},{"id":"3-g3","no":3,"cn":"语气副词“真”","en":"The Modal Adverb 真","note":"真 shows a subjective exclamation, while 很 merely states a high degree. 真 cannot modify a noun directly.","subs":[{"id":"a","label":"真 + adj","exp":"Exclamation (\"really\")."},{"id":"b","label":"很 + adj","exp":"Plain statement of degree."}],"items":[{"c":"你女儿的房间真漂亮！","en":"Your daughter's room is really beautiful!","sub":"a","lv":2},{"c":"今天真热！","en":"It's really hot today!","sub":"a","lv":1},{"c":"我今天很忙。","en":"I am very busy today.","sub":"b","lv":1},{"c":"我今天很生气。","en":"I am very angry today.","sub":"b","lv":1},{"c":"认识你很高兴。","en":"Nice to meet you.","sub":"b","lv":1},{"c":"这道题目真简单。","en":"This question is really easy.","sub":"a","lv":2},{"c":"你的新衣服真好看！","en":"Your new clothes are really nice!","sub":"a","lv":2},{"c":"这个苹果真甜！","en":"This apple is really sweet!","sub":"a","lv":2},{"c":"今天的天气很好。","en":"The weather is very good today.","sub":"b","lv":2},{"c":"这本书很有意思。","en":"This book is very interesting.","sub":"b","lv":2},{"c":"你买的衣服真漂亮！","en":"The clothes you bought are really pretty!","sub":"a","lv":2},{"c":"他做的饭真好吃。","en":"The food he makes is really tasty.","sub":"b","lv":2},{"c":"这个女孩真漂亮！","en":"This girl is really pretty!","sub":"a","lv":2},{"c":"你做的菜真好吃！","en":"The food you make is really tasty!","sub":"a","lv":2},{"c":"这个电影很有意思。","en":"This movie is very interesting.","sub":"b","lv":2},{"c":"他说的那个故事很有意思。","en":"The story he told is very interesting.","sub":"b","lv":3},{"c":"你买的这个包真好看！","en":"This bag you bought is really nice!","sub":"a","lv":3},{"c":"他做的这个菜真好吃！","en":"This dish he made is really tasty!","sub":"a","lv":3},{"c":"他说的那个电影很有意思。","en":"That movie he mentioned is very interesting.","sub":"b","lv":3}]},{"id":"3-g4","no":4,"cn":"疑问代词“哪”+量词","en":"哪 + measure word (\"which\")","tag":"extended","tags":["TEXT"],"note":"哪 + measure word asks \"which (one)\" and always needs a measure word (哪个 / 哪种 / 哪本 / 哪件). It can stand alone as subject or object, or sit before a noun.","subs":[{"id":"a","label":"哪 + M + N？","exp":"As subject or object: which one."},{"id":"b","label":"哪 + M + N","exp":"Before a noun: which + noun."}],"items":[{"c":"哪个是你的？","en":"Which one is yours?","sub":"a","lv":2},{"c":"你喜欢哪个？","en":"Which one do you like?","sub":"a","lv":1},{"c":"你喜欢哪种水果？","en":"Which kind of fruit do you like?","sub":"b","lv":1},{"c":"哪本书是你的？","en":"Which book is yours?","sub":"b","lv":2},{"c":"你喜欢哪件？","en":"Which one do you like?","sub":"a","lv":1},{"c":"你要买哪个？","en":"Which one do you want to buy?","sub":"a","lv":1},{"c":"哪个是你的杯子？","en":"Which one is your cup?","sub":"a","lv":2},{"c":"你要买哪件衣服？","en":"Which piece of clothing do you want to buy?","sub":"b","lv":1},{"c":"你住哪个房间？","en":"Which room do you live in?","sub":"b","lv":1},{"c":"你坐哪辆公共汽车？","en":"Which bus do you take?","sub":"b","lv":1},{"c":"你觉得我做的哪个菜最好吃？","en":"Which dish I made do you think is the tastiest?","sub":"a","lv":3},{"c":"你说的哪句话是真的？","en":"Which of the things you said is true?","sub":"b","lv":2},{"c":"你喜欢哪个颜色的衣服？","en":"Which colour of clothing do you like?","sub":"a","lv":2},{"c":"你喜欢我买的哪件衣服？","en":"Which piece of clothing I bought do you like?","sub":"a","lv":2},{"c":"你要买哪个牌子的手机？","en":"Which brand of phone do you want to buy?","sub":"b","lv":2},{"c":"你觉得我买哪个牌子的手机好？","en":"Which brand of phone do you think I should buy?","sub":"b","lv":3},{"c":"你觉得我买的哪个手机最好用？","en":"Which phone I bought do you think is easiest to use?","sub":"a","lv":3},{"c":"你说的哪句话最有意思？","en":"Which sentence you said is the most interesting?","sub":"b","lv":3}]}]},{"lesson":4,"key":"4","review":false,"title":"He recommended me for this job","titleCn":"这个工作是他帮我介绍的","points":[{"id":"4-g1","no":1,"cn":"“是……的”句：强调施事","en":"The 是……的 Sentence: Emphasizing the Agent","note":"是……的 highlights an already-known fact, emphasising who did it, or when / where / how. The two sentences with 了 alone (我买了一本汉语书 / 昨天我去故宫了) belong to 了, not here.","subs":[{"id":"a","label":"是 + S + V + 的","exp":"Emphasises the agent."},{"id":"b","label":"不 + 是 + S + V + 的","exp":"Negative form."}],"items":[{"c":"这个工作是他帮我介绍的。","en":"He recommended me for this job.","sub":"a","lv":3},{"c":"他是昨天来的。","en":"It was yesterday that he came.","sub":"a","lv":2},{"c":"电话（不）是我打的。","en":"I am (not) the one who made the call.","sub":"b","lv":1},{"c":"我是坐飞机来的。","en":"I came by plane.","sub":"a","lv":1},{"c":"是我买的。","en":"It was I who bought it.","sub":"a","lv":2},{"c":"是妈妈做的。","en":"Mum made it.","sub":"a","lv":2},{"c":"他是坐火车来的。","en":"He came by train.","sub":"a","lv":1},{"c":"不是我买的。","en":"It wasn't bought by me.","sub":"b","lv":2},{"c":"不是妈妈做的。","en":"It wasn't made by Mum.","sub":"b","lv":2},{"c":"不是他告诉我的。","en":"He didn't tell me (it wasn't him).","sub":"b","lv":2},{"c":"不是昨天来的。","en":"It wasn't yesterday that he came.","sub":"b","lv":1},{"c":"这本书是我买的。","en":"This book was bought by me.","sub":"a","lv":3},{"c":"那个蛋糕是他做的。","en":"That cake was made by him.","sub":"a","lv":3},{"c":"这本书是我昨天在书店买的。","en":"I bought this book at the bookshop yesterday.","sub":"a","lv":2},{"c":"那个蛋糕是妈妈为我做的。","en":"That cake was made for me by Mum.","sub":"a","lv":3},{"c":"这个手机不是他买的。","en":"This phone wasn't bought by him.","sub":"b","lv":3},{"c":"这个蛋糕不是妈妈做的。","en":"This cake wasn't made by Mum.","sub":"b","lv":3}]},{"id":"4-g2","no":2,"cn":"表示时间：“……的时候”","en":"Expressing Time: ……的时候","note":"……的时候 marks \"when / at the time of\". It follows the clause that names the time.","subs":[{"id":"a","label":"Clause + 的时候","exp":"\"When …\"."},{"id":"b","label":"……的时候，……","exp":"Time clause + main clause."}],"items":[{"c":"我十一岁的时候开始踢足球。","en":"I started playing football when I was eleven.","sub":"a","lv":3},{"c":"吃饭的时候不要说话。","en":"Don't talk while eating.","sub":"b","lv":3},{"c":"下雨的时候我在家。","en":"I was at home when it rained.","sub":"b","lv":3},{"c":"我累的时候想休息。","en":"When I'm tired I want to rest.","sub":"a","lv":3},{"c":"他生病的时候没来。","en":"When he was sick he didn't come.","sub":"b","lv":3},{"c":"你走的时候告诉我。","en":"Tell me when you leave.","sub":"a","lv":2},{"c":"我小的时候住在北京。","en":"When I was little I lived in Beijing.","sub":"a","lv":3},{"c":"你买东西的时候要想一想。","en":"Think it over when you buy things.","sub":"a","lv":3},{"c":"看电视的时候，不要说话。","en":"Don't talk while watching TV.","sub":"b","lv":3},{"c":"睡觉的时候，他喜欢听音乐。","en":"When sleeping, he likes to listen to music.","sub":"b","lv":3}]},{"id":"4-g3","no":3,"cn":"时间副词“已经”","en":"The Time Adverb 已经","note":"已经 marks that something has already happened. It usually pairs with a sentence-final 了.","subs":[{"id":"a","label":"已经 + V + 了","exp":"Action already completed."},{"id":"b","label":"已经 + Time/V + 了","exp":"With a time expression."}],"items":[{"c":"我已经踢了十年足球了。","en":"I have played football for ten years already.","sub":"a","lv":2},{"c":"他已经走了。","en":"He has already left.","sub":"a","lv":1},{"c":"现在已经十二点了。","en":"It is already twelve o'clock.","sub":"b","lv":2},{"c":"我已经起床了。","en":"I've already got up.","sub":"a","lv":1},{"c":"他已经休息了。","en":"He's already rested.","sub":"a","lv":1},{"c":"现在已经很晚了。","en":"It's already quite late now.","sub":"b","lv":2},{"c":"我已经吃完了。","en":"I've already finished eating.","sub":"a","lv":2},{"c":"已经是秋天了。","en":"It's already autumn.","sub":"b","lv":1},{"c":"已经三天了。","en":"It's already been three days.","sub":"b","lv":2},{"c":"已经下班了。","en":"It's already time to get off work.","sub":"b","lv":1},{"c":"我买的书已经看完了。","en":"I've already finished reading the book I bought.","sub":"a","lv":3},{"c":"老师说的话我已经忘了。","en":"I've already forgotten what the teacher said.","sub":"a","lv":2},{"c":"你买的那个手机已经两年了。","en":"The phone you bought has been with you for two years already.","sub":"b","lv":3},{"c":"我买的那个电脑已经半年了","en":"I've had the computer I bought for half a year already.","sub":"b","lv":3},{"c":"我买的这个手机已经用两年了。","en":"I've already used this phone I bought for two years.","sub":"a","lv":3}]},{"id":"4-g4","no":4,"cn":"疑问代词“谁”","en":"The Interrogative Pronoun 谁","tag":"extended","tags":["TEXT"],"note":"谁 asks \"who\"; 谁的 means \"whose\". Like other interrogative pronouns it keeps the same position as the person it replaces — it does not move to the front.","subs":[{"id":"a","label":"谁 + V？","exp":"谁 as subject or object: who."},{"id":"b","label":"谁的","exp":"谁的 = whose."}],"items":[{"c":"电话是谁打的？","en":"Who made the call?","sub":"a","lv":1},{"c":"谁在门外？","en":"Who is outside?","sub":"a","lv":2},{"c":"你喜欢谁？","en":"Who do you like?","sub":"a","lv":1},{"c":"这是谁的？","en":"Whose is this?","sub":"b","lv":1},{"c":"谁在叫你？","en":"Who is calling you?","sub":"a","lv":2},{"c":"谁买了这本书？","en":"Who bought this book?","sub":"a","lv":2},{"c":"这是谁的书？","en":"Whose book is this?","sub":"b","lv":1},{"c":"那件衣服是谁的？","en":"Whose clothing is that?","sub":"b","lv":2},{"c":"这个手机是谁的？","en":"Whose phone is this?","sub":"b","lv":2},{"c":"这些苹果是谁的？","en":"Whose apples are these?","sub":"b","lv":2},{"c":"谁买的那本书？","en":"Who bought that book?","sub":"a","lv":2},{"c":"这是谁做的饭？","en":"Whose cooking is this?","sub":"b","lv":1},{"c":"谁看了我买的这本书？","en":"Who read this book I bought?","sub":"a","lv":3},{"c":"谁吃了妈妈做的这个蛋糕？","en":"Who ate this cake Mum made?","sub":"a","lv":3},{"c":"你昨天买的那本书是谁的？","en":"Whose is the book you bought yesterday?","sub":"b","lv":3},{"c":"你用的那个手机是谁的？","en":"Whose is the phone you are using?","sub":"b","lv":3}]}]},{"lesson":5,"key":"5","review":false,"title":"Take this one","titleCn":"就买这件吧","points":[{"id":"5-g1","no":1,"cn":"副词“就”（1）","en":"The Adverb 就 (1)","note":"就 (1) at L5: it settles on a choice (\"just / simply\") and affirms firmly.","subs":[{"id":"a","label":"就 + V","exp":"Settling on a choice — \"just do it\"."},{"id":"b","label":"S + 就 + 是/在 + N","exp":"Affirming firmly — \"this is exactly…\"."},{"id":"c","label":"（clause），就是 + clause","exp":"就是 = \"but / only\" — a mild turn (the one shortcoming)."}],"items":[{"c":"就买这件吧。","en":"Let's just buy this one.","sub":"a","lv":2},{"c":"他就吃面条。","en":"He'll just have noodles.","sub":"a","lv":1},{"c":"他就是我的老师。","en":"He is exactly my teacher.","sub":"b","lv":2},{"c":"这就是我的家。","en":"This is my home right here.","sub":"b","lv":2},{"c":"书就在桌子上面。","en":"The book is right on the desk.","sub":"b","lv":2},{"c":"咖啡不好喝，就喝牛奶吧。","en":"The coffee is not good — let's just have milk.","sub":"a","lv":1},{"c":"我喜欢买东西，就买了这件衣服。","en":"I like shopping, so I just bought this piece of clothing.","sub":"a","lv":2},{"c":"我晚上有时间，就去打球吧。","en":"If I have time tonight, let's just go play ball.","sub":"a","lv":1},{"c":"我朋友喜欢打球，就去打球吧。","en":"My friend likes playing ball, so let's just go play ball.","sub":"a","lv":1},{"c":"今天我很累，我们就休息吧。","en":"I'm tired today — let's just rest.","sub":"a","lv":2},{"c":"累了就休息吧。","en":"If you're tired, just rest.","sub":"a","lv":1},{"c":"这个咖啡馆不错，就喝咖啡吧。","en":"This café is nice — let's just have coffee here.","sub":"a","lv":2},{"c":"下雨了就不出门吧。","en":"It's raining, so let's just not go out.","sub":"a","lv":1},{"c":"你不想去，就在家休息吧。","en":"If you don't want to go, just rest at home.","sub":"a","lv":2},{"c":"就在家做你爱吃的鱼吧。","en":"Let's just make the fish you love at home.","sub":"a","lv":3},{"c":"颜色还可以，就是有点儿大。","en":"The colour is fine, but it's a bit big.","sub":"c","lv":2},{"c":"这个房间不错，就是有点儿小。","en":"This room is nice, but a bit small.","sub":"c","lv":2},{"c":"我很想去，就是没时间。","en":"I'd love to go, but I have no time.","sub":"c","lv":1},{"c":"他就是我哥哥。","en":"He is my older brother.","sub":"b","lv":1},{"c":"图书馆就在学校旁边。","en":"The library is right next to the school.","sub":"b","lv":2},{"c":"这个手机很好，就是太贵了。","en":"This phone is good, but too expensive.","sub":"c","lv":2},{"c":"衣服很好看，就是有点儿大。","en":"The clothes are nice, but a bit big.","sub":"c","lv":2},{"c":"这就是我买的那个手机。","en":"This is exactly the phone I bought.","sub":"b","lv":3},{"c":"你要是喜欢我买的那个，就买那个吧。","en":"If you like the one I bought, just buy that one.","sub":"a","lv":3},{"c":"这就是他说的那个饭馆。","en":"This is exactly the restaurant he mentioned.","sub":"b","lv":3},{"c":"这个房子不错，就是他说的价钱太贵了。","en":"The flat is nice, but the price he mentioned is too high.","sub":"c","lv":3},{"c":"衣服很好看，就是妈妈买的那件有点儿大。","en":"The clothes are nice, but the one Mum bought is a bit big.","sub":"c","lv":3}]},{"id":"5-g2","no":2,"cn":"语气副词“还”（1）","en":"The Modal Adverb 还 (1)","note":"还 (1) at L5: a state or degree still holds, or the degree is only \"fairly / so-so\".","subs":[{"id":"a","label":"还 + adj","exp":"\"Fairly / still\" — a moderate degree."},{"id":"b","label":"还 + V","exp":"A state or action still continues."}],"items":[{"c":"我觉得听和说还可以，读和写不好。","en":"I think listening and speaking are okay, but reading and writing are not.","sub":"a","lv":2},{"c":"现在还早呢。","en":"It's still early.","sub":"a","lv":2},{"c":"他还在教室学习呢。","en":"He is still studying in the classroom.","sub":"b","lv":2},{"c":"这块手表还不错。","en":"This watch is not bad.","sub":"a","lv":2},{"c":"他还不知道。","en":"He still doesn't know yet.","sub":"b","lv":1},{"c":"我还没休息呢。","en":"I haven't rested yet.","sub":"b","lv":1},{"c":"这件衣服还可以。","en":"This piece of clothing is okay.","sub":"a","lv":2},{"c":"天气还不错。","en":"The weather is not bad.","sub":"a","lv":1},{"c":"他还在工作。","en":"He is still working.","sub":"b","lv":2},{"c":"我还没吃饭。","en":"I haven't eaten yet.","sub":"b","lv":1},{"c":"我买了一件衣服，还不错。","en":"I bought a piece of clothing, and it is not bad.","sub":"a","lv":2},{"c":"他还在看我买的书。","en":"He is still reading the book I bought.","sub":"b","lv":3},{"c":"他还在用我买的手机。","en":"He is still using the phone I bought.","sub":"b","lv":3},{"c":"你买的这件衣服还不错。","en":"The piece of clothing you bought is not bad.","sub":"a","lv":3},{"c":"他做的菜还可以。","en":"The food he makes is okay.","sub":"a","lv":2},{"c":"他还在看这本书。","en":"He is still reading this book.","sub":"b","lv":2},{"c":"他还在用这个手机。","en":"He is still using this phone.","sub":"b","lv":2},{"c":"你买的这个手机还不错。","en":"This phone you bought is not bad.","sub":"a","lv":3}]},{"id":"5-g3","no":3,"cn":"程度副词“有点儿”","en":"The Adverb of Degree 有点儿","note":"有点儿 expresses a small degree and usually carries a tone of dissatisfaction.","subs":[{"id":"a","label":"有点儿 + adj","exp":"Slightly (and not desirable)."}],"items":[{"c":"这件衣服有点儿大。","en":"This piece of clothing is a bit too big.","sub":"a","lv":2},{"c":"他今天有点儿不高兴。","en":"He is a bit unhappy today.","sub":"a","lv":1},{"c":"俄语有点儿难。","en":"Russian is a bit difficult.","sub":"a","lv":1},{"c":"我有点儿累。","en":"I'm a bit tired.","sub":"a","lv":1},{"c":"这个房间有点儿小。","en":"This room is a bit small.","sub":"a","lv":2},{"c":"今天有点儿忙。","en":"I'm a bit busy today.","sub":"a","lv":1},{"c":"今天的饭有点儿少。","en":"Today's food is a bit little.","sub":"a","lv":2},{"c":"你买的这件衣服有点儿大。","en":"This piece of clothing you bought is a bit big.","sub":"a","lv":3},{"c":"他做的菜有点儿咸。","en":"The food he cooks is a bit salty.","sub":"a","lv":2},{"c":"他做的这个菜有点儿咸。","en":"This dish he made is a bit salty.","sub":"a","lv":3}]},{"id":"5-g4","no":4,"cn":"语气助词“吧”","en":"The Modal Particle 吧","note":"吧 softens a sentence: it can guess, suggest, or give permission.","subs":[{"id":"a","label":"Sentence + 吧","exp":"Guessing about something uncertain."},{"id":"b","label":"Sentence + 吧","exp":"Making a suggestion or request."},{"id":"c","label":"Sentence + 吧","exp":"Agreeing or giving permission."}],"items":[{"c":"这辆车很贵吧？","en":"This car is expensive, isn't it?","sub":"a","lv":2},{"c":"你们认识吧？","en":"You know each other, right?","sub":"a","lv":1},{"c":"你快去开会吧。","en":"Hurry up and go to the meeting.","sub":"b","lv":2},{"c":"你昨天太累了，今天就在家休息吧。","en":"You were too tired yesterday — just rest at home today.","sub":"b","lv":2},{"c":"请你帮我一下吧。","en":"Please give me a hand.","sub":"b","lv":2},{"c":"可以，就这样吧。","en":"Fine, let's leave it at that.","sub":"c","lv":1},{"c":"你坐吧。","en":"Have a seat.","sub":"c","lv":1},{"c":"你是学生吧？","en":"You're a student, right?","sub":"a","lv":1},{"c":"明天会下雨吧？","en":"It will rain tomorrow, won't it?","sub":"a","lv":1},{"c":"他不在家吧？","en":"He's not at home, is he?","sub":"a","lv":2},{"c":"我们一起去吧。","en":"Let's go together.","sub":"b","lv":1},{"c":"你早点儿休息吧。","en":"Rest early.","sub":"b","lv":1},{"c":"好吧，我听你的。","en":"Okay, I'll listen to you.","sub":"c","lv":2},{"c":"行，就这么办吧。","en":"Okay, let's do it this way.","sub":"c","lv":1},{"c":"没问题，你来吧。","en":"No problem, come over.","sub":"c","lv":1},{"c":"这就是我跟你说的那个饭馆吧？","en":"This is the restaurant I told you about, right?","sub":"a","lv":3},{"c":"这个手机很贵吧？","en":"This phone is expensive, isn't it?","sub":"a","lv":2},{"c":"你买的这个手机很贵吧？","en":"The phone you bought is expensive, isn't it?","sub":"a","lv":3},{"c":"你穿我买的这件衣服吧。","en":"Wear this piece of clothing I bought.","sub":"b","lv":3},{"c":"你吃妈妈做的菜吧。","en":"Have some of the food Mum made.","sub":"b","lv":2},{"c":"行，就买这个吧。","en":"Fine, let's just buy this one.","sub":"c","lv":2},{"c":"好，我们坐这个车吧。","en":"Okay, let's take this bus.","sub":"c","lv":2},{"c":"好吧，就按他说的办吧。","en":"Okay, let's do it the way he said.","sub":"c","lv":2},{"c":"你吃我做的这个菜吧。","en":"Have this dish I made.","sub":"b","lv":3},{"c":"好，我们就买他说的那个吧。","en":"Okay, let's just buy that one he mentioned.","sub":"c","lv":3},{"c":"行，就用我买的这个吧。","en":"Fine, let's just use this one I bought.","sub":"c","lv":3}]},{"id":"5-g5","no":5,"cn":"数量词“一点儿”","en":"The Quantifier 一点儿","note":"一点儿 is a quantity word meaning \"a little / a bit\". Unlike 有点儿 it is neutral and can follow a verb or an adjective+了.","subs":[{"id":"a","label":"V + 一点儿 + (N)","exp":"\"A little of something\" — with a verb."},{"id":"b","label":"adj + 了 + 一点儿","exp":"\"A bit more … than before\" — with a change of state."}],"items":[{"c":"以后我少喝一点儿。","en":"I'll drink a bit less from now on.","sub":"a","lv":2},{"c":"来一点儿面条吧。","en":"Have a bit of noodles.","sub":"a","lv":2},{"c":"我去买一点儿葡萄。","en":"I'll go buy some grapes.","sub":"a","lv":2},{"c":"这条裤子长了一点儿。","en":"These trousers are a bit too long.","sub":"b","lv":2},{"c":"他比我高一点儿。","en":"He is a little taller than me.","sub":"b","lv":2},{"c":"我想喝一点儿水。","en":"I want to drink a little water.","sub":"a","lv":2},{"c":"你吃一点儿水果吧。","en":"Eat a little fruit.","sub":"a","lv":2},{"c":"这件衣服贵了一点儿。","en":"This clothing is a bit expensive.","sub":"b","lv":2},{"c":"今天冷了一点儿。","en":"It's a bit colder today.","sub":"b","lv":2},{"c":"他说话快了一点儿。","en":"He speaks a bit fast.","sub":"b","lv":2},{"c":"你买的东西多了一点儿。","en":"You bought a bit too many things.","sub":"b","lv":3},{"c":"我买的衣服贵了一点儿。","en":"The clothing I bought was a bit too expensive.","sub":"b","lv":3},{"c":"你尝一点儿我做的菜。","en":"Try a bit of the food I made.","sub":"a","lv":3},{"c":"我买一点儿他说的那种水果。","en":"I'll buy a bit of that fruit he mentioned.","sub":"a","lv":3}]},{"id":"5-g6","no":6,"cn":"进行态：是……吗？/ 在 + V","en":"Progressive: 在 + V and the Emphatic 是……吗？","note":"在 + V states an action in progress. Adding 是 before 在 emphasises the question (\"is it … that you are doing?\"), and the answer often uses 不是……，我在…… to correct it.","subs":[{"id":"a","label":"（是）在 + V + 吗？","exp":"Asks whether an action is in progress — \"are you (in the middle of) doing …?\""},{"id":"b","label":"不是……，我在 + V","exp":"Corrects the guess: \"no, I am doing …\"."}],"items":[{"c":"你是在看电视吗？","en":"Are you watching TV?","sub":"a","lv":2},{"c":"是在想昨天的考试吗？","en":"Are you thinking about yesterday's exam?","sub":"a","lv":2},{"c":"是在想昨天的天气吗？","en":"Are you thinking about yesterday's weather?","sub":"a","lv":2},{"c":"是在想昨天吃的饭吗？","en":"Are you thinking about yesterday's meal?","sub":"a","lv":2},{"c":"是在想妈妈做的鱼吗？","en":"Are you thinking about the fish mum made?","sub":"a","lv":3},{"c":"是在想跟朋友玩吗？","en":"Are you thinking about playing with friends?","sub":"a","lv":2},{"c":"我不是在看电视，我在玩电脑。","en":"I'm not watching TV — I'm playing on the computer.","sub":"b","lv":2},{"c":"我不是在睡觉，我在看书。","en":"I'm not sleeping, I'm reading.","sub":"b","lv":2},{"c":"我不是在打电话，我在听音乐。","en":"I'm not calling, I'm listening to music.","sub":"b","lv":2},{"c":"我不是在做饭，我在洗碗。","en":"I'm not cooking, I'm washing dishes.","sub":"b","lv":2},{"c":"我不是在写作业，我在画画。","en":"I'm not doing homework, I'm drawing.","sub":"b","lv":2},{"c":"你是在看我买的书吗？","en":"Are you reading the book I bought?","sub":"a","lv":3},{"c":"你是在吃他做的饭吗？","en":"Are you eating the food he cooked?","sub":"a","lv":3},{"c":"我不是在看这本书，我在看那个。","en":"I'm not reading this book — I'm reading that one.","sub":"b","lv":2},{"c":"我不是在看我买的书，我在看他的。","en":"I'm not reading the book I bought — I'm reading his.","sub":"b","lv":3},{"c":"他不是在吃我做的饭，他在吃面条。","en":"He isn't eating the food I made — he's eating noodles.","sub":"b","lv":3}]},{"id":"5-g7","no":7,"cn":"「……多了」表示过量","en":"V + 多了 — Excess","note":"V + 多了 means an action has been done to excess (\"too much / too many times\"), and it usually leads to a bad result: ……多了对身体不好. The remedy uses 少 + V + 一点儿.","subs":[{"id":"a","label":"V + 多了 + 对身体不好","exp":"Doing something too much is bad for you."},{"id":"b","label":"少 + V + 一点儿","exp":"The remedy — do it a bit less."}],"items":[{"c":"咖啡喝多了对身体不好。","en":"Drinking too much coffee is bad for your health.","sub":"a","lv":2},{"c":"电脑玩多了对身体不好。","en":"Spending too much time on the computer is bad for your health.","sub":"a","lv":2},{"c":"手机玩多了对身体不好。","en":"Using your phone too much is bad for your health.","sub":"a","lv":2},{"c":"不运动对身体不好。","en":"Not exercising is bad for your health.","sub":"a","lv":2},{"c":"运动太多也对身体不好。","en":"Exercising too much is also bad for you.","sub":"a","lv":2},{"c":"以后我少喝一点儿，每天喝一杯。","en":"From now on I'll drink a bit less — one cup a day.","sub":"b","lv":2},{"c":"以后你少看一点儿电视。","en":"Watch less TV from now on.","sub":"b","lv":2},{"c":"你少说一点儿话。","en":"Talk less.","sub":"b","lv":2},{"c":"以后我少喝一点儿咖啡。","en":"Drink less coffee from now on.","sub":"b","lv":2},{"c":"你少吃一点儿糖。","en":"Eat less candy.","sub":"b","lv":2},{"c":"抽烟对身体不好。","en":"Smoking is bad for your health.","sub":"a","lv":2},{"c":"熬夜对身体不好。","en":"Staying up late is bad for your health.","sub":"a","lv":2},{"c":"你买的这个游戏玩多了对眼睛不好。","en":"Playing the game you bought too much is bad for your eyes.","sub":"a","lv":3},{"c":"你以后少吃一点儿他做的菜。","en":"Eat a bit less of the food he cooks from now on.","sub":"b","lv":3},{"c":"酒喝多了对眼睛不好。","en":"Drinking too much alcohol is bad for your eyes.","sub":"a","lv":2,"tags":["COLLOC"]},{"c":"糖吃多了对牙不好。","en":"Eating too much sugar is bad for your teeth.","sub":"a","lv":2,"tags":["COLLOC"]},{"c":"这种游戏玩多了对眼睛不好。","en":"Playing this kind of game too much is bad for your eyes.","sub":"a","lv":2},{"c":"你买的这种游戏玩多了对眼睛不好。","en":"Playing this kind of game you bought too much is bad for your eyes.","sub":"a","lv":3},{"c":"你以后少喝一点儿他买的咖啡。","en":"Drink a bit less of the coffee he bought from now on.","sub":"b","lv":3}]}]},{"lesson":6,"key":"6","review":false,"title":"Why don't you eat more","titleCn":"你怎么不吃了","points":[{"id":"6-g1","no":1,"cn":"疑问代词“怎么”","en":"The Interrogative Pronoun 怎么","note":"怎么 asks \"how\" about a manner, and can also express surprise or puzzlement.","subs":[{"id":"a","label":"怎么 + V？","exp":"How? / in what way?"},{"id":"b","label":"怎么 + 不 + V？","exp":"Why not…? (surprise)"}],"items":[{"c":"昨天你们怎么都没去打篮球？","en":"Why didn't any of you go play basketball yesterday?","sub":"b","lv":1},{"c":"你怎么去学校？","en":"How do you get to school?","sub":"a","lv":1},{"c":"这个字怎么写？","en":"How do you write this character?","sub":"a","lv":2},{"c":"你怎么知道？","en":"How do you know?","sub":"a","lv":1},{"c":"这个词怎么读？","en":"How do you read this word?","sub":"a","lv":2},{"c":"你怎么不去？","en":"Why don't you go?","sub":"b","lv":1},{"c":"这个菜怎么做？","en":"How do you make this dish?","sub":"a","lv":2},{"c":"你怎么不睡觉？","en":"Why aren't you sleeping?","sub":"b","lv":1},{"c":"他怎么不说话？","en":"Why isn't he talking?","sub":"b","lv":1},{"c":"你们怎么不去上课？","en":"Why don't you go to class?","sub":"b","lv":1},{"c":"这个字怎么写，你能告诉我一下吗？","en":"How do you write this character? Could you tell me?","sub":"a","lv":3},{"c":"你怎么不去买一件新衣服？","en":"Why don't you go and buy a new piece of clothing?","sub":"b","lv":2},{"c":"你知道我买的这个东西怎么用吗？","en":"Do you know how to use the thing I bought?","sub":"a","lv":3},{"c":"你告诉我他做的菜怎么做。","en":"Tell me how the food he cooks is made.","sub":"a","lv":2},{"c":"手机上的字怎么读？","en":"How do you read the characters on the phone?","sub":"a","lv":2},{"c":"你的名字怎么写？","en":"How do you write your name?","sub":"a","lv":2},{"c":"你怎么不喝一点儿水？","en":"Why don't you drink a bit of water?","sub":"b","lv":2},{"c":"你怎么不吃我做的菜？","en":"Why aren't you eating the food I made?","sub":"b","lv":2},{"c":"他怎么不去老师说的那个地方？","en":"Why isn't he going to the place the teacher mentioned?","sub":"b","lv":3},{"c":"你怎么不吃我做的这个菜？","en":"Why aren't you eating this dish I made?","sub":"b","lv":3}]},{"id":"6-g2","no":2,"cn":"量词的重叠","en":"Reduplication of Measure Words","note":"Measure words can be reduplicated to mean \"every / one after another\".","subs":[{"id":"a","label":"M + M + 都","exp":"Every single one."},{"id":"b","label":"天天 / 个个","exp":"Common reduplicated forms."}],"items":[{"c":"这个星期我天天吃羊肉。","en":"I ate mutton every day this week.","sub":"b","lv":2},{"c":"这些苹果个个都很大。","en":"Every one of these apples is big.","sub":"a","lv":2},{"c":"他天天去游泳。","en":"He goes swimming every day.","sub":"b","lv":1},{"c":"我天天早上跑步。","en":"I run every morning.","sub":"b","lv":1},{"c":"这些字个个都很难。","en":"Every one of these characters is hard.","sub":"a","lv":2},{"c":"这些菜个个都很好吃。","en":"Every one of these dishes is delicious.","sub":"a","lv":2},{"c":"这些包个个都很贵。","en":"Every one of these bags is expensive.","sub":"a","lv":2},{"c":"这些字个个都会写。","en":"I can write every one of these characters.","sub":"a","lv":2},{"c":"我天天坐公共汽车上班。","en":"I take the bus to work every day.","sub":"b","lv":1},{"c":"他天天看书。","en":"He reads every day.","sub":"b","lv":1},{"c":"这些书一本一本都很好看。","en":"Every one of these books is nice.","sub":"a","lv":2},{"c":"他年年都来一次。","en":"He comes once every year.","sub":"b","lv":2},{"c":"妈妈买的苹果个个都很大。","en":"Every one of the apples Mum bought is big.","sub":"a","lv":3},{"c":"我买的衣服件件都很便宜。","en":"Every piece of clothing I bought is cheap.","sub":"b","lv":3},{"c":"他年年都去北京。","en":"He goes to Beijing every year.","sub":"b","lv":1,"tags":["COLLOC"]},{"c":"这家店月月都有新东西。","en":"This shop has new things every month.","sub":"b","lv":2,"tags":["COLLOC"]},{"c":"春节的时候，家家都吃饺子。","en":"At Spring Festival every family eats dumplings.","sub":"b","lv":3,"tags":["COLLOC"]},{"c":"老师说的那些字个个都很难。","en":"Every one of the characters the teacher mentioned is hard.","sub":"a","lv":3}]},{"id":"6-g3","no":3,"cn":"关联词“因为……所以”","en":"The Conjunction 因为……所以","note":"因为……所以…… gives a cause and its result. Either half may be omitted in speech.","subs":[{"id":"a","label":"因为……，所以……","exp":"Full cause-and-effect pair."},{"id":"b","label":"因为……，……","exp":"所以 omitted."}],"items":[{"c":"因为昨天下雨，所以我们都没去打篮球。","en":"Because it rained yesterday, none of us went to play basketball.","sub":"a","lv":1},{"c":"因为太忙，他没来。","en":"Because he was too busy, he didn't come.","sub":"b","lv":2},{"c":"因为工作太忙了，所以我不能去旅游。","en":"Because work is too busy, I can't go travelling.","sub":"a","lv":2},{"c":"因为汉字太难了，所以我不喜欢写汉字。","en":"Because Chinese characters are too hard, I don't like writing them.","sub":"a","lv":2},{"c":"因为下雨了，所以不能去跑步。","en":"Because it's raining, we can't go running.","sub":"a","lv":1},{"c":"因为身体不好，所以天天吃药。","en":"Because his health is poor, he takes medicine every day.","sub":"a","lv":2},{"c":"因为下雨，我们没去公园。","en":"Because it rained, we didn't go to the park.","sub":"b","lv":1},{"c":"因为太贵，我没买。","en":"Because it was too expensive, I didn't buy it.","sub":"b","lv":2},{"c":"因为生病，他没来上课。","en":"Because he was sick, he didn't come to class.","sub":"b","lv":1},{"c":"因为工作忙，我很少回家。","en":"Because I'm busy with work, I rarely go home.","sub":"b","lv":2},{"c":"因为买了一件新衣服，所以我很高兴。","en":"Because I bought a new piece of clothing, I am very happy.","sub":"a","lv":2},{"c":"因为下了一天雨，我们没出去。","en":"Because it rained for a whole day, we didn't go out.","sub":"b","lv":2},{"c":"因为考试的时候太紧张，所以没考好。","en":"Because I was too nervous during the exam, I didn't do well.","sub":"a","lv":3},{"c":"因为他说的话太难，我没听懂。","en":"Because what he said was too difficult, I didn't understand.","sub":"b","lv":3},{"c":"因为妈妈做的菜太好吃，所以我吃了很多。","en":"Because Mum's cooking was so tasty, I ate a lot.","sub":"a","lv":3},{"c":"因为老师说的那个地方太远，我们没去。","en":"Because the place the teacher mentioned was too far, we didn't go.","sub":"b","lv":3}]}]},{"lesson":7,"key":"7","review":false,"title":"Do you live far from your company","titleCn":"你家离公司远吗","points":[{"id":"7-g1","no":1,"cn":"语气副词“还”（2）","en":"The Modal Adverb 还 (2)","note":"还 (2) at L7: the three main uses — continuation, repetition, and a further supplement.","subs":[{"id":"a","label":"还 1 · 状态持续","exp":"It's used to indicate the continuation of an action or a state."},{"id":"b","label":"还 2 · 动作重复","exp":"It's used to indicate the repetition of an action."},{"id":"c","label":"还 3 · 补充追加","exp":"It's used to make a further supplement for what was mentioned before."}],"items":[{"c":"他还在教室学习呢。","en":"He is still studying in the classroom.","sub":"a","lv":2},{"c":"现在还在下雨。","en":"It's still raining now.","sub":"a","lv":2},{"c":"窗户还开着呢。","en":"The window is still open.","sub":"a","lv":1},{"c":"昨天吃了饺子，今天我还想吃。","en":"I had dumplings yesterday; today I still want them.","sub":"b","lv":1},{"c":"你已经喝了三杯咖啡了，还要喝？","en":"You've already had three cups of coffee — you still want more?","sub":"b","lv":2},{"c":"我喜欢看电视，还喜欢听音乐。","en":"I like watching TV, and I also like listening to music.","sub":"c","lv":1},{"c":"单词学完了以后，你们还要多复习几遍。","en":"After finishing the words, you still need to review them a few more times.","sub":"c","lv":2},{"c":"他还在睡觉。","en":"He is still sleeping.","sub":"a","lv":2},{"c":"灯还亮着。","en":"The light is still on.","sub":"a","lv":1},{"c":"我还想吃。","en":"I still want to eat more.","sub":"b","lv":1},{"c":"明天还去吗？","en":"Are we going again tomorrow?","sub":"b","lv":1},{"c":"我还想再听一遍。","en":"I want to listen one more time.","sub":"b","lv":2},{"c":"他会唱歌，还会跳舞。","en":"He can sing, and he can dance too.","sub":"c","lv":1},{"c":"我要买书，还要买笔。","en":"I want to buy books, and pens too.","sub":"c","lv":1},{"c":"他喜欢运动，还喜欢旅游。","en":"He likes exercise, and travelling too.","sub":"c","lv":1},{"c":"他还在看我买的书。","en":"He is still reading the book I bought.","sub":"a","lv":3},{"c":"我喜欢看书，还喜欢看老师推荐的书。","en":"I like reading, and I also like reading the books the teacher recommended.","sub":"c","lv":2},{"c":"他还在看这本书。","en":"He is still reading this book.","sub":"a","lv":2},{"c":"他还在用妈妈的手机。","en":"He is still using Mum's phone.","sub":"a","lv":2},{"c":"他还在用我买的那个手机。","en":"He is still using the phone I bought.","sub":"a","lv":3},{"c":"你买的这个电影我还想看。","en":"I still want to see this movie you bought.","sub":"b","lv":3},{"c":"老师推荐的那本书我还想再读一遍。","en":"I want to read that book the teacher recommended once more.","sub":"b","lv":3},{"c":"他会唱这首歌，还会跳那个舞。","en":"He can sing this song and also dance that dance.","sub":"c","lv":2},{"c":"他要买我推荐的那本书，还要买笔。","en":"He wants to buy the book I recommended and also some pens.","sub":"c","lv":3},{"c":"他还在看那本书。","en":"He is still reading that book.","sub":"a","lv":2},{"c":"我喜欢这本书，还喜欢他推荐的那本。","en":"I like this book and also the one he recommended.","sub":"c","lv":3},{"c":"我看了他推荐的那部电影，还想再看一遍。","en":"I've seen the movie he recommended, and I'd like to watch it again.","sub":"b","lv":3},{"c":"昨天我跟妈妈去了老师说的那个公园，明天还想去。","en":"Yesterday I went to the park the teacher mentioned with my mom, and I want to go again tomorrow.","sub":"b","lv":3},{"c":"因为那家饭馆的菜太好吃了，我们明天还想去。","en":"The food at that restaurant was so good that we want to go again tomorrow.","sub":"b","lv":3}]},{"id":"7-g2","no":2,"cn":"时间副词“就”（2）","en":"The Time Adverb 就 (2)","note":"就 (2) at L7: it stresses that something happens early, quickly, or as soon as expected.","subs":[{"id":"a","label":"S + Time + 就 + V + 了","exp":"\"As early as / by then already\"."},{"id":"b","label":"就 + V","exp":"Right away."},{"id":"c","label":"一……就……","exp":"\"As soon as … then …\"."},{"id":"d","label":"S + Time + 就 + V + 了（takes only a short time）","exp":"With a duration, 就 stresses how little time it takes — \"only … and already\"."}],"items":[{"c":"我二十分钟就到。","en":"I'll be there in twenty minutes.","sub":"a","lv":1},{"c":"他七点就来了。","en":"He came as early as seven.","sub":"a","lv":2},{"c":"我就来。","en":"I'm coming right away.","sub":"b","lv":1},{"c":"我马上就来。","en":"I'll be right there.","sub":"b","lv":1},{"c":"我到了北京就给你打电话。","en":"I'll call you as soon as I arrive in Beijing.","sub":"c","lv":2},{"c":"同学们七点半就来教室了。","en":"The classmates came to the classroom as early as 7:30.","sub":"a","lv":2},{"c":"我六点半就起床了。","en":"I got up as early as 6:30.","sub":"a","lv":2},{"c":"我男朋友五点就做晚饭了。","en":"My boyfriend made dinner as early as five.","sub":"a","lv":2},{"c":"我坐飞机一个半小时就到北京了。","en":"A 1.5-hour flight and I'm already in Beijing.","sub":"d","lv":2},{"c":"我打车半小时就到餐馆了。","en":"A half-hour taxi ride and I'm already at the restaurant.","sub":"d","lv":1},{"c":"我走路七分钟就到教室了。","en":"A seven-minute walk and I'm already at the classroom.","sub":"d","lv":1},{"c":"我打车五分钟就到医院了。","en":"A five-minute taxi ride and I'm already at the hospital.","sub":"d","lv":1},{"c":"我坐公交车十五分钟就到星巴克了。","en":"A fifteen-minute bus ride and I'm already at Starbucks.","sub":"d","lv":1},{"c":"我就去。","en":"I'll go right away.","sub":"b","lv":1},{"c":"我这就来。","en":"I'm coming right now.","sub":"b","lv":1},{"c":"他马上就回来。","en":"He'll be back soon.","sub":"b","lv":1},{"c":"我一回家就睡觉。","en":"I go to bed as soon as I get home.","sub":"c","lv":2},{"c":"他一到学校就开始学习。","en":"He starts studying as soon as he gets to school.","sub":"c","lv":1},{"c":"我一看见他就笑。","en":"I laugh as soon as I see him.","sub":"c","lv":3},{"c":"我们一吃完饭就走。","en":"We leave as soon as we finish eating.","sub":"c","lv":2},{"c":"坐地铁二十分钟就到了。","en":"It's only twenty minutes by metro and you're there.","sub":"d","lv":1},{"c":"我一看见他就想起以前的事。","en":"As soon as I see him I think of the past.","sub":"c","lv":3},{"c":"他一听老师说的话就笑了。","en":"As soon as he heard what the teacher said, he laughed.","sub":"c","lv":2},{"c":"我骑自行车十分钟就到他说的那个地方了。","en":"Ten minutes by bike and I was at the place he mentioned.","sub":"d","lv":3},{"c":"他说的那个电影七点就开始了。","en":"That movie he mentioned starts as early as seven.","sub":"a","lv":3},{"c":"我买的那个蛋糕昨天就吃完了。","en":"The cake I bought was finished as early as yesterday.","sub":"a","lv":3},{"c":"你等一下，我就来。","en":"Wait a moment, I am coming right away.","sub":"b","lv":2},{"c":"饭马上就好，你再等一下。","en":"The food will be ready right away, wait a bit.","sub":"b","lv":2},{"c":"你买的那本书我马上就看完了。","en":"I am just about to finish the book you bought.","sub":"b","lv":3},{"c":"他做的菜马上就好。","en":"The food he makes will be ready right away.","sub":"b","lv":2},{"c":"我骑车十分钟就到那个公园了。","en":"I got to that park in ten minutes by bike.","sub":"d","lv":2},{"c":"我走他说的那条路十分钟就到了。","en":"I took the road he mentioned and got there in ten minutes.","sub":"d","lv":3},{"c":"他推荐的那个电影我下午就看。","en":"I will watch that movie he recommended this afternoon.","sub":"b","lv":3},{"c":"因为学校离家很近，我走路十分钟就到了。","en":"School is close to home, so I get there in ten minutes on foot.","sub":"d","lv":3},{"c":"从我家坐地铁到老师说的那个公司，二十分钟就到了。","en":"The subway from my home to the company the teacher mentioned takes only twenty minutes.","sub":"d","lv":3},{"c":"从公司打车去他推荐的那家饭馆，十五分钟就到了。","en":"A taxi from the office to the restaurant he recommended takes only fifteen minutes.","sub":"d","lv":3}]},{"id":"7-g3","no":3,"cn":"动词“离”","en":"The Verb 离","note":"离 states the distance between two places, or the time remaining before an event.","subs":[{"id":"a","label":"A + 离 + B + 远/近","exp":"Distance in space."},{"id":"b","label":"A + 离 + B + 时间/距离","exp":"With a measure phrase."}],"items":[{"c":"你家离公司远吗？","en":"Is your home far from the company?","sub":"a","lv":1},{"c":"我家离学校很远。","en":"My home is far from the school.","sub":"a","lv":2},{"c":"公司离这里很近。","en":"The company is very close to here.","sub":"a","lv":2},{"c":"超市离我家两百米。","en":"The supermarket is 200 metres from my home.","sub":"b","lv":2},{"c":"你家离学校远吗？","en":"Is your home far from the school?","sub":"a","lv":1},{"c":"公园离餐馆远吗？","en":"Is the park far from the restaurant?","sub":"a","lv":1},{"c":"你家离公司有多远？","en":"How far is your home from the company?","sub":"b","lv":1},{"c":"你家到学校要多长时间？","en":"How long does it take from your home to the school?","sub":"b","lv":1},{"c":"离我的生日还有一个多星期。","en":"There's still over a week until my birthday.","sub":"b","lv":2},{"c":"离考试还有三天。","en":"There are still three days until the exam.","sub":"b","lv":2},{"c":"离新年还有两个月。","en":"There are still two months until New Year.","sub":"b","lv":2},{"c":"他家离我买的房子很近。","en":"His home is very close to the house I bought.","sub":"a","lv":3},{"c":"离老师说的时间还有半个小时。","en":"There is still half an hour until the time the teacher said.","sub":"b","lv":3},{"c":"他家离我买的那个房子很近。","en":"His home is close to the flat I bought.","sub":"a","lv":3},{"c":"离他说的那个日子还有一个星期。","en":"There is still a week until that date he mentioned.","sub":"b","lv":3},{"c":"他买的那个房子离公司很近。","en":"The apartment he bought is close to his company.","sub":"a","lv":3},{"c":"我们家附近那家饭馆离公司不远，但是味道很好。","en":"The restaurant near our home isn't far from the office, but the food is great.","sub":"a","lv":3},{"c":"我买的这个房子离他说的那个地铁站很近。","en":"The apartment I bought is close to the subway station he mentioned.","sub":"a","lv":3}]},{"id":"7-g4","no":4,"cn":"语气助词“呢”","en":"The Modal Particle 呢","note":"呢 at the end of a sentence softens the tone, or signals that a situation is ongoing.","subs":[{"id":"a","label":"Sentence + 呢","exp":"Softening / reminding."},{"id":"b","label":"…在… + 呢","exp":"Continuous action."}],"items":[{"c":"坐公共汽车要一个多小时呢！","en":"Taking the bus takes more than an hour!","sub":"a","lv":2},{"c":"他在教室学习呢。","en":"He is studying in the classroom.","sub":"b","lv":2},{"c":"这本书很贵呢！","en":"This book is really expensive!","sub":"a","lv":2},{"c":"他还没来呢。","en":"He hasn't come yet.","sub":"a","lv":1},{"c":"今天很冷呢。","en":"It's really cold today.","sub":"a","lv":2},{"c":"那件衣服很好看呢。","en":"That clothing is really pretty.","sub":"a","lv":2},{"c":"他在看电视呢。","en":"He's watching TV.","sub":"b","lv":2},{"c":"妈妈在做饭呢。","en":"Mum is cooking.","sub":"b","lv":2},{"c":"我们在上课呢。","en":"We're in class.","sub":"b","lv":2},{"c":"她在唱歌呢。","en":"She's singing.","sub":"b","lv":2},{"c":"这个包两百多块钱呢！","en":"This bag is over two hundred yuan!","sub":"a","lv":2},{"c":"他在吃我买的蛋糕呢。","en":"He is eating the cake I bought.","sub":"b","lv":3},{"c":"你说的那个人我认识呢。","en":"I know that person you're talking about.","sub":"a","lv":3},{"c":"你说的那个饭馆我很喜欢呢。","en":"I really like that restaurant you mentioned.","sub":"a","lv":3},{"c":"他在看这本书呢。","en":"He is reading this book.","sub":"b","lv":2},{"c":"他在看我买的这本书呢。","en":"He is reading this book I bought.","sub":"b","lv":3}]},{"id":"7-g5","no":5,"cn":"介词“给”","en":"The Preposition 给","tag":"extended","tags":["TEXT"],"note":"给 + person + V means doing something for or to that person.","subs":[{"id":"a","label":"给 + 人 + V","exp":"For / to someone."}],"items":[{"c":"我给你过生日。","en":"I'll celebrate your birthday for you.","sub":"a","lv":1},{"c":"我给大卫打个电话。","en":"I'll give David a call.","sub":"a","lv":1},{"c":"妈妈给我做饭。","en":"Mum cooks for me.","sub":"a","lv":1},{"c":"老师给我们上课。","en":"The teacher teaches us.","sub":"a","lv":1},{"c":"朋友给我买咖啡。","en":"My friend buys me coffee.","sub":"a","lv":1},{"c":"我给妈妈买了一件衣服。","en":"I bought a piece of clothing for Mum.","sub":"a","lv":2,"tags":["COLLOC"]},{"c":"他给我介绍了他的朋友。","en":"He introduced his friend to me.","sub":"a","lv":2,"tags":["COLLOC"]},{"c":"请你给我们唱一个歌。","en":"Please sing a song for us.","sub":"a","lv":3},{"c":"他给我看他买的照片。","en":"He showed me the photos he bought.","sub":"a","lv":2},{"c":"妈妈给我做了我最喜欢的菜。","en":"Mum cooked my favourite dish for me.","sub":"a","lv":2},{"c":"妈妈给我做了她做的那个菜。","en":"Mum made me that dish she makes.","sub":"a","lv":3}]}]},{"lesson":8,"key":"8","review":false,"title":"Let me think about it and I'll tell you later","titleCn":"让我想想再告诉你","points":[{"id":"8-g1","no":1,"cn":"疑问句“，好吗？”","en":"The Question Form ，好吗？","note":"，好吗？ tacks a request for agreement onto a statement — \"…, okay?\"","subs":[{"id":"a","label":"statement，好吗？","exp":"Asks for the listener's consent."}],"items":[{"c":"我们下午去看电影，好吗？","en":"Let's go see a movie this afternoon, okay?","sub":"a","lv":1},{"c":"我们一起去吃饭，好吗？","en":"Let's go eat together, okay?","sub":"a","lv":1},{"c":"我们明天再一起去，好吗？","en":"Let's go again together tomorrow, ok?","sub":"a","lv":1},{"c":"你帮帮我，好吗？","en":"Can you help me, please?","sub":"a","lv":2},{"c":"我们一起回家，好吗？","en":"Let's go home together, ok?","sub":"a","lv":1},{"c":"你坐下，好吗？","en":"Sit down, okay?","sub":"a","lv":1},{"c":"你明天早一点儿来，好吗？","en":"Come a bit earlier tomorrow, okay?","sub":"a","lv":2},{"c":"你坐我买的新车，好吗？","en":"Ride the new car I bought, okay?","sub":"a","lv":2},{"c":"你穿他买的那件衣服，好吗？","en":"Wear the piece of clothing he bought, okay?","sub":"a","lv":3},{"c":"你穿他买的这件衣服，好吗？","en":"Wear this piece of clothing he bought, okay?","sub":"a","lv":3}]},{"id":"8-g2","no":2,"cn":"副词“再”","en":"The Adverb 再","note":"再 means \"again\" for a future or repeated action, and can also mean \"then, after that\".","subs":[{"id":"a","label":"再 + V","exp":"Do it again."},{"id":"b","label":"Time + 再 + V","exp":"Do it again later."},{"id":"c","label":"V1 + 再 + V2","exp":"Do V1, then V2."}],"items":[{"c":"你让我想想再告诉你。","en":"Let me think it over and then tell you.","sub":"c","lv":3},{"c":"你再看一下这本书吧。","en":"Take another look at this book.","sub":"a","lv":2},{"c":"你明天再给我打电话吧。","en":"Call me again tomorrow.","sub":"b","lv":2},{"c":"你再说一遍。","en":"Please say it again.","sub":"a","lv":2},{"c":"我们再听一遍。","en":"Let's listen again.","sub":"a","lv":2},{"c":"你再写一次。","en":"Please write it once more.","sub":"a","lv":2},{"c":"我想再看一次那个电影。","en":"I want to watch that movie one more time.","sub":"a","lv":2},{"c":"我们明天再见面。","en":"Let's meet again tomorrow.","sub":"b","lv":1},{"c":"你下午再来吧。","en":"Come again in the afternoon.","sub":"b","lv":1},{"c":"我下个星期再去北京。","en":"I'll go to Beijing again next week.","sub":"b","lv":1},{"c":"他明年再学汉语。","en":"He'll learn Chinese again next year.","sub":"b","lv":1},{"c":"你先吃饭再学习。","en":"Eat first, then study.","sub":"c","lv":1},{"c":"我写完作业再出去玩。","en":"I'll finish my homework first, then go out to play.","sub":"c","lv":2},{"c":"你先想一想再回答。","en":"Think it over first, then answer.","sub":"c","lv":1},{"c":"我们吃完饭再去看电影。","en":"We'll go to the movies after we finish eating.","sub":"c","lv":2},{"c":"你吃完我做的饭再走。","en":"Finish the food I made before you go.","sub":"c","lv":3},{"c":"你听完老师说的话再问。","en":"Listen to what the teacher says before you ask.","sub":"c","lv":3},{"c":"你再看一下我买的那本书。","en":"Have another look at the book I bought.","sub":"a","lv":3},{"c":"你再听一遍老师说的话。","en":"Listen to what the teacher said one more time.","sub":"a","lv":3},{"c":"你明天再看这个电影吧。","en":"Watch this movie tomorrow instead.","sub":"b","lv":2},{"c":"你下午再吃这个药吧。","en":"Take this medicine in the afternoon instead.","sub":"b","lv":2},{"c":"你明天再穿他买的那件衣服吧。","en":"Wear that piece of clothing he bought tomorrow instead.","sub":"b","lv":3},{"c":"你吃完以后再看老师推荐的那本书。","en":"After eating, read that book the teacher recommended.","sub":"b","lv":3}]},{"id":"8-g3","no":3,"cn":"兼语句","en":"Pivotal Sentences","note":"A pivotal sentence has the object of the first verb serve as the subject of the second (让 / 叫 / 请).","subs":[{"id":"a","label":"A + 让/叫/请 + B + V","exp":"B does the second action."},{"id":"b","label":"A + 让 + B + V + (O)","exp":"With an object."}],"items":[{"c":"我叫人去看看。","en":"I'll have someone go and take a look.","sub":"a","lv":1},{"c":"妈妈让我早点儿回家。","en":"Mother let me go home a bit earlier.","sub":"b","lv":2},{"c":"老师让我们读课文。","en":"The teacher had us read the text.","sub":"b","lv":2},{"c":"请你帮我一下吧。","en":"Please give me a hand.","sub":"a","lv":2},{"c":"老师叫我们写作业。","en":"The teacher told us to do our homework.","sub":"a","lv":2},{"c":"妈妈让我早点儿睡觉。","en":"Mum asked me to go to bed early.","sub":"a","lv":2},{"c":"爸爸叫我去商店买牛奶。","en":"Dad asked me to go to the shop to buy milk.","sub":"a","lv":2},{"c":"朋友请我吃饭。","en":"A friend invited me to dinner.","sub":"b","lv":2},{"c":"王老师让我给大卫打电话。","en":"Mr Wang asked me to give David a call.","sub":"b","lv":2},{"c":"妈妈让我买水果。","en":"Mum asked me to buy some fruit.","sub":"b","lv":2},{"c":"老师叫我们读这几篇课文。","en":"The teacher asked us to read these few texts.","sub":"a","lv":3},{"c":"妈妈让我买这个星期的菜。","en":"Mum asked me to buy this week's vegetables.","sub":"a","lv":3},{"c":"他让我用他买的那个手机。","en":"He asked me to use that phone he bought.","sub":"b","lv":3},{"c":"老师让我们看这部新电影。","en":"The teacher asked us to watch this new movie.","sub":"b","lv":3}]},{"id":"8-g4","no":4,"cn":"动词的重叠","en":"Reduplication of Verbs","note":"Verbs are reduplicated to show a short, casual or tentative action.","subs":[{"id":"aa","label":"单音节 · AA / A一A","exp":"Monosyllabic verbs: AA or A一A, meaning \"do sth a little / give it a try\"."},{"id":"abab","label":"双音节 · ABAB","exp":"Disyllabic verbs: ABAB, meaning \"do sth a little / take a short break\"."}],"items":[{"c":"看—看看—看一看","en":"look — have a look — take a look","sub":"aa","lv":1},{"c":"说—说说—说一说","en":"speak — have a talk — say a bit","sub":"aa","lv":1},{"c":"听—听听—听一听","en":"listen — give a listen — take a listen","sub":"aa","lv":1},{"c":"等—等等—等一等","en":"wait — wait a bit — wait a moment","sub":"aa","lv":1},{"c":"介绍—介绍介绍","en":"introduce — give a brief introduction","sub":"abab","lv":1},{"c":"休息—休息休息","en":"rest — take a little rest","sub":"abab","lv":1},{"c":"准备—准备准备","en":"prepare — do a bit of preparation","sub":"abab","lv":1},{"c":"运动—运动运动","en":"exercise — do some exercise","sub":"abab","lv":1},{"c":"玩—玩玩—玩一玩","en":"play — play a little — play a bit","sub":"aa","lv":1},{"c":"学习—学习学习","en":"study — do a little studying","sub":"abab","lv":1},{"c":"你看看这本书。","en":"Have a look at this book.","sub":"aa","lv":2},{"c":"你试试这件衣服。","en":"Try this piece of clothing.","sub":"aa","lv":2},{"c":"我们商量商量这件事。","en":"Let's talk this matter over.","sub":"abab","lv":2},{"c":"你看看我买的那本书。","en":"Have a look at the book I bought.","sub":"aa","lv":3},{"c":"我们商量商量老师说的那件事。","en":"Let's talk over the matter the teacher mentioned.","sub":"abab","lv":3},{"c":"你看看他买的那辆车。","en":"Have a look at that car he bought.","sub":"aa","lv":3},{"c":"我们准备准备这个考试吧。","en":"Let us do some preparation for this exam.","sub":"abab","lv":2},{"c":"我们商量商量他说的那件事。","en":"Let us talk over that matter he mentioned.","sub":"abab","lv":3},{"c":"你看看这本书，虽然很贵，但是很有用。","en":"Take a look at this book — it's expensive but very useful.","sub":"aa","lv":3},{"c":"你试试我买的这双鞋，比你的舒服多了。","en":"Try on the shoes I bought; they're much more comfortable than yours.","sub":"aa","lv":3},{"c":"因为明天就要出发了，我们在教室里商量商量这次旅行吧。","en":"Let's discuss this trip in the classroom since we leave tomorrow.","sub":"abab","lv":3},{"c":"我们准备准备他说的那个考试，因为下周就要考了。","en":"Let's get ready for the exam he mentioned, since it's next week.","sub":"abab","lv":3}]},{"id":"8-g5","no":5,"cn":"形容词的重叠","en":"Reduplication of Adjectives","note":"Monosyllabic adjectives can be reduplicated (AA + 的) to stress a deep degree or affection. No degree adverb may precede them.","subs":[{"id":"a","label":"AA + 的","exp":"Reduplicated adjective as predicate."},{"id":"b","label":"AA + 的 + N","exp":"As an attributive."}],"items":[{"c":"这个苹果甜甜的。","en":"This apple is nice and sweet.","sub":"a","lv":2},{"c":"他的手大大的。","en":"His hands are big.","sub":"a","lv":1},{"c":"我的头发长长的。","en":"My hair is long.","sub":"a","lv":1},{"c":"她有一双大大的眼睛。","en":"She has a pair of big eyes.","sub":"b","lv":2},{"c":"房间小小的。","en":"The room is a bit small.","sub":"a","lv":1},{"c":"眼睛红红的。","en":"The eyes are a bit red.","sub":"a","lv":1},{"c":"她有一张圆圆的脸。","en":"She has a round face.","sub":"b","lv":2},{"c":"小狗有一双小小的耳朵。","en":"The puppy has a pair of small ears.","sub":"b","lv":2},{"c":"妈妈给我买了一顶红红的帽子。","en":"Mum bought me a red hat.","sub":"b","lv":2},{"c":"他有一双长长的腿。","en":"He has a pair of long legs.","sub":"b","lv":2},{"c":"他写的字大大的。","en":"The characters he writes are nice and big.","sub":"b","lv":2},{"c":"她买的那件衣服红红的。","en":"The piece of clothing she bought is red.","sub":"a","lv":3},{"c":"那个房间小小的。","en":"That room is quite small.","sub":"a","lv":2},{"c":"你买的那个包小小的。","en":"That bag you bought is quite small.","sub":"a","lv":3},{"c":"那家饭馆小小的，但是菜很好吃。","en":"That restaurant is tiny, but the food is delicious.","sub":"a","lv":3},{"c":"这儿的房间小小的，但是很便宜。","en":"The rooms here are small, but very cheap.","sub":"a","lv":3},{"c":"我买的这个包红红的，比她的好看多了。","en":"The bag I bought is bright red and much nicer-looking than hers.","sub":"a","lv":3}]}]},{"lesson":9,"key":"9","review":false,"title":"There were too many questions; I didn't finish all of them","titleCn":"题太多，我没做完","points":[{"id":"9-g1","no":1,"cn":"结果补语","en":"The Result Complement","note":"A result complement follows the verb to show the outcome of the action (完 / 懂 / 好 / 到 / 见).","subs":[{"id":"a","label":"S + V + result + (O)","exp":"Affirmative."},{"id":"b","label":"S + 没（有）+ V + result + (O)","exp":"Negative with 没."},{"id":"c","label":"S + V + result + (O) + 了没有？","exp":"Affirmative-negative question."}],"items":[{"c":"我的作业做完了。","en":"I finished my homework.","sub":"a","lv":2},{"c":"我听见了。","en":"I heard it.","sub":"a","lv":1},{"c":"我的作业没做完。","en":"I didn't finish my homework.","sub":"b","lv":2},{"c":"你的作业做完了没有？","en":"Have you finished your homework?","sub":"c","lv":2},{"c":"我看完了那个电影。","en":"I finished watching that movie.","sub":"a","lv":2},{"c":"你找到钥匙了吗？","en":"Did you find the key?","sub":"c","lv":1},{"c":"我找到钥匙了。","en":"I found the key.","sub":"a","lv":1},{"c":"他吃完了。","en":"He finished eating.","sub":"a","lv":1},{"c":"我还没看见他。","en":"I still haven't seen him.","sub":"b","lv":2},{"c":"他没找到钱包。","en":"He didn't find his wallet.","sub":"b","lv":1},{"c":"我没听懂老师的话。","en":"I didn't understand what the teacher said.","sub":"b","lv":2},{"c":"她没看完那本书。","en":"She didn't finish reading that book.","sub":"b","lv":2},{"c":"你听懂了吗？","en":"Did you understand it?","sub":"c","lv":1},{"c":"你吃完了没有？","en":"Have you finished eating?","sub":"c","lv":1},{"c":"你看见他了吗？","en":"Did you see him?","sub":"c","lv":2},{"c":"我买的那本书看完了。","en":"I've finished reading the book I bought.","sub":"a","lv":3},{"c":"他做的饭我吃完了。","en":"I finished the food he cooked.","sub":"a","lv":2},{"c":"我没看完他买的那本书。","en":"I haven't finished reading that book he bought.","sub":"b","lv":3},{"c":"他没有听见老师说的话。","en":"He didn't hear what the teacher said.","sub":"b","lv":2},{"c":"你买的那本书看完了没有？","en":"Have you finished reading the book you bought?","sub":"c","lv":3},{"c":"他做的饭你吃完了没有？","en":"Have you finished the food he made?","sub":"c","lv":2},{"c":"他做的这个菜我吃完了。","en":"I finished this dish he made.","sub":"a","lv":3},{"c":"我没看完他买的这本书。","en":"I haven't finished reading this book he bought.","sub":"b","lv":3},{"c":"他做的这个蛋糕你吃完了没有？","en":"Have you finished this cake he made?","sub":"c","lv":3}]},{"id":"9-g2","no":2,"cn":"介词“从”","en":"The Preposition 从","note":"从 marks the starting point of a place, time or range; 从……到…… means \"from … to …\".","subs":[{"id":"a","label":"从 + place/time + V","exp":"Starting point."},{"id":"b","label":"从……到……","exp":"From … to …"}],"items":[{"c":"我从早上八点开始上课。","en":"I start class at eight in the morning.","sub":"a","lv":2},{"c":"你从第二个词开始读。","en":"Start reading from the second word.","sub":"a","lv":2},{"c":"从北京到上海要坐几个小时的飞机？","en":"How many hours by plane from Beijing to Shanghai?","sub":"b","lv":2},{"c":"从三号到五号公司放假。","en":"The company is closed from the 3rd to the 5th.","sub":"b","lv":1},{"c":"我从北京坐飞机到上海。","en":"I flew from Beijing to Shanghai.","sub":"b","lv":1},{"c":"你从哪里来？","en":"Where do you come from?","sub":"a","lv":1},{"c":"我们从学校出发。","en":"We set off from the school.","sub":"a","lv":1},{"c":"他从北京来。","en":"He comes from Beijing.","sub":"a","lv":1},{"c":"从星期一到星期五我都要上课。","en":"I have classes from Monday to Friday.","sub":"b","lv":1},{"c":"从家到学校走路十分钟。","en":"It's a ten-minute walk from home to school.","sub":"b","lv":1},{"c":"从早上八点到下午五点我都有课。","en":"I have classes from eight in the morning to five in the afternoon.","sub":"b","lv":2},{"c":"从他说的地方往前走。","en":"Walk forward from the place he mentioned.","sub":"a","lv":2},{"c":"从老师推荐的那本书开始读。","en":"Start reading from the book the teacher recommended.","sub":"a","lv":3},{"c":"从我家到他说的那个学校要走二十分钟。","en":"It takes twenty minutes to walk from my home to that school he mentioned.","sub":"b","lv":3},{"c":"从这儿到老师推荐的那个公园很近。","en":"It is very close from here to that park the teacher recommended.","sub":"b","lv":3},{"c":"我从老师推荐的那本书开始读。","en":"I started reading from that book the teacher recommended.","sub":"a","lv":3},{"c":"因为从这儿到那个公园很近，我每天都走路去。","en":"It's close from here to that park, so I walk there every day.","sub":"b","lv":3},{"c":"从我家到老师说的那个公园很近。","en":"It's very close from my home to the park the teacher mentioned.","sub":"b","lv":3},{"c":"从他说的那个地铁站到公司很近，走路只要十分钟。","en":"From the subway station he mentioned to the office is close — only ten minutes on foot.","sub":"b","lv":3}]},{"id":"9-g3","no":3,"cn":"“第…”表示顺序","en":"第… for Ordinal Numbers","note":"第 before a number forms an ordinal: first, second, third …","subs":[{"id":"a","label":"第 + Number","exp":"Ordinal number."},{"id":"b","label":"第 + Number + M + N","exp":"As an attributive."}],"items":[{"c":"第一个人","en":"The first person","sub":"a","lv":2},{"c":"第二个星期","en":"The second week","sub":"a","lv":2},{"c":"这是我第一次来中国。","en":"This is my first time in China.","sub":"b","lv":2},{"c":"第三天","en":"The third day","sub":"a","lv":2},{"c":"第四次","en":"The fourth time","sub":"a","lv":2},{"c":"第五个","en":"The fifth one","sub":"a","lv":2},{"c":"这是我的第一个工作。","en":"This is my first job.","sub":"b","lv":2},{"c":"他住在第三层。","en":"He lives on the third floor.","sub":"b","lv":2},{"c":"我第一次坐飞机。","en":"This is my first time taking a plane.","sub":"b","lv":2},{"c":"这是我第二次来北京。","en":"This is my second time coming to Beijing.","sub":"b","lv":2},{"c":"第一。","en":"The first.","sub":"a","lv":1},{"c":"第三。","en":"The third.","sub":"a","lv":1},{"c":"我买的第一个手机坏了。","en":"The first phone I bought broke.","sub":"b","lv":3},{"c":"他说的第一句话我没听懂。","en":"I didn't understand the first sentence he said.","sub":"b","lv":3}]},{"id":"9-g4","no":4,"cn":"可能补语","en":"The Potential Complement","note":"A potential complement uses 得/不 between the verb and its complement to say whether a result is possible.","subs":[{"id":"a","label":"V + 得 + complement","exp":"Possible / able to."},{"id":"b","label":"V + 不 + complement","exp":"Impossible / unable to."},{"id":"c","label":"V + 得 + complement + 吗？","exp":"Question form."}],"items":[{"c":"我听得见他说话。","en":"I can hear him speaking.","sub":"a","lv":1},{"c":"我看得见那座山。","en":"I can see that mountain.","sub":"a","lv":2},{"c":"我学不会那首歌。","en":"I can't learn that song.","sub":"b","lv":2},{"c":"我没学会那首歌。","en":"I didn't manage to learn that song.","sub":"b","lv":2},{"c":"你看得见吗？","en":"Can you see it?","sub":"c","lv":1},{"c":"我听得懂汉语。","en":"I can understand Chinese.","sub":"a","lv":1},{"c":"我学得会这首歌。","en":"I can learn this song.","sub":"a","lv":2},{"c":"这么多作业，我做得完。","en":"There's a lot of homework, but I can finish it.","sub":"a","lv":1},{"c":"我听不懂他说话。","en":"I can't understand what he says.","sub":"b","lv":1},{"c":"这么多题，我做不完。","en":"There are too many questions; I can't finish them.","sub":"b","lv":1},{"c":"我找不着钥匙。","en":"I can't find the key.","sub":"b","lv":1},{"c":"你听得懂吗？","en":"Can you understand?","sub":"c","lv":1},{"c":"你做得完吗？","en":"Can you finish it?","sub":"c","lv":1},{"c":"你学得会吗？","en":"Can you learn it?","sub":"c","lv":1},{"c":"你看得清楚吗？","en":"Can you see it clearly?","sub":"c","lv":1},{"c":"我买的书你看得完吗？","en":"Can you finish the books I bought?","sub":"c","lv":2},{"c":"他说的那句话你听得懂吗？","en":"Can you understand that sentence he said?","sub":"c","lv":3},{"c":"老师推荐的那本书你看得懂吗？","en":"Can you understand that book the teacher recommended?","sub":"a","lv":3},{"c":"我写的那些字你看得清楚吗？","en":"Can you see the characters I wrote clearly?","sub":"a","lv":3},{"c":"他买的那个手机我用不了。","en":"I can't use that phone he bought.","sub":"b","lv":3},{"c":"老师说的话我记不住。","en":"I can't remember what the teacher said.","sub":"b","lv":2},{"c":"我听得懂这个老师的话。","en":"I can understand this teacher's words.","sub":"c","lv":2},{"c":"我做得完这些作业。","en":"I can finish this homework.","sub":"c","lv":2},{"c":"他买的这个手机我用不了。","en":"I can't use this phone he bought.","sub":"b","lv":3},{"c":"我做的这些菜你吃得完吗？","en":"Can you finish all these dishes I made?","sub":"c","lv":3},{"c":"因为老师说得太快，我一句都听不懂。","en":"The teacher spoke too fast, so I couldn't understand a single sentence.","sub":"a","lv":3},{"c":"我买的那台电脑很贵，他修得好吗？","en":"The computer I bought was expensive — can he fix it?","sub":"a","lv":3},{"c":"老师推荐的那本书很有意思，你看得完吗？","en":"The book the teacher recommended is very interesting — can you finish it?","sub":"a","lv":3}]},{"id":"9-g5","no":5,"cn":"介词“跟”","en":"The Preposition 跟","note":"跟 introduces the person one does something with, learns from, or is compared to.","tag":"extended","tags":["TEXT"],"subs":[{"id":"a","label":"跟 + 人 + V","exp":"Doing something together with / learning from someone."},{"id":"b","label":"跟 + 人 + 一起 + V","exp":"Together with someone."},{"id":"c","label":"跟 + 人 + 一样","exp":"The same as someone."}],"items":[{"c":"我跟老师学跳舞。","en":"I learn dancing from the teacher.","sub":"a","lv":1},{"c":"我女儿想跟您学跳舞。","en":"My daughter wants to learn dancing from you.","sub":"a","lv":1},{"c":"你跟谁学汉语？","en":"Who do you learn Chinese from?","sub":"a","lv":1},{"c":"他经常跟朋友聊天。","en":"He often chats with friends.","sub":"a","lv":1},{"c":"我跟妈妈说一件事。","en":"I'll tell Mum something.","sub":"a","lv":2},{"c":"我跟朋友一起去看电影。","en":"I go to the movies with my friends.","sub":"b","lv":1},{"c":"他跟哥哥一起踢足球。","en":"He plays football with his brother.","sub":"b","lv":1},{"c":"你跟谁一起去北京？","en":"Who are you going to Beijing with?","sub":"b","lv":1},{"c":"我跟妈妈一起去买东西。","en":"I go shopping with my mum.","sub":"b","lv":1},{"c":"他跟同学们一起学习汉语。","en":"He studies Chinese with his classmates.","sub":"b","lv":1},{"c":"我跟你一样高。","en":"I'm as tall as you.","sub":"c","lv":1},{"c":"这件衣服跟那件一样。","en":"This piece of clothing is the same as that one.","sub":"c","lv":2},{"c":"他的汉语跟中国人一样好。","en":"His Chinese is as good as a native speaker’s.","sub":"c","lv":2},{"c":"我的手机跟你的不一样。","en":"My phone is different from yours.","sub":"c","lv":2},{"c":"这个苹果跟那个一样大。","en":"This apple is as big as that one.","sub":"c","lv":2},{"c":"我跟他说的话他都不听。","en":"He doesn't listen to anything I say to him.","sub":"a","lv":2},{"c":"我买的手机跟他的一样。","en":"The phone I bought is the same as his.","sub":"c","lv":2},{"c":"我跟这个老师学汉语。","en":"I learn Chinese with this teacher.","sub":"a","lv":2},{"c":"我跟他说的那个老师学汉语。","en":"I learn Chinese with that teacher he mentioned.","sub":"a","lv":3},{"c":"我跟老师推荐的那个学生一起学习。","en":"I study together with that student the teacher recommended.","sub":"b","lv":3},{"c":"他跟我买的那个班的同学一起打球。","en":"He plays ball with the classmates from that class I signed up for.","sub":"b","lv":3},{"c":"你说的那个饭馆跟我家楼下的那个一样。","en":"That restaurant you mentioned is the same as the one downstairs from my home.","sub":"c","lv":3},{"c":"我跟这个同学一起学习。","en":"I study together with this classmate.","sub":"b","lv":2},{"c":"我跟老师推荐的那个同学一起学习汉语。","en":"I study Chinese together with that classmate the teacher recommended.","sub":"b","lv":3},{"c":"我买的这个手机跟他的一样。","en":"This phone I bought is the same as his.","sub":"c","lv":3},{"c":"我跟老师推荐的那个同学学汉语。","en":"I learn Chinese with that classmate the teacher recommended.","sub":"a","lv":3},{"c":"我跟那个同学一起学习。","en":"I study together with that classmate.","sub":"b","lv":2}]}]},{"lesson":10,"key":"10","review":false,"title":"Stop looking for your cell phone; it's on the desk","titleCn":"别找了，手机在桌子上呢","points":[{"id":"10-g1","no":1,"cn":"祈使句：不要……了/别……了","en":"Imperatives: 不要……了 / 别……了","note":"别 and 不要 both forbid an action. 别 is more colloquial; a sentence-final 了 often follows.","subs":[{"id":"a","label":"不要 + V + (O) + 了","exp":"Prohibition."},{"id":"b","label":"别 + V + (O) + 了","exp":"Colloquial prohibition."}],"items":[{"c":"不要看电视了。","en":"Stop watching TV.","sub":"a","lv":1},{"c":"不要坐。","en":"Don't sit here.","sub":"a","lv":1},{"c":"别看报纸了。","en":"Stop reading the newspaper.","sub":"b","lv":1},{"c":"别说话了。","en":"Stop talking.","sub":"b","lv":1},{"c":"别高兴了。","en":"Don't get too excited.","sub":"b","lv":1},{"c":"不要说话了。","en":"Stop talking.","sub":"a","lv":1},{"c":"不要玩了，去学习吧。","en":"Stop playing, go study.","sub":"a","lv":1},{"c":"不要吃了，你已经吃得很多了。","en":"Stop eating, you've already eaten a lot.","sub":"a","lv":2},{"c":"别买了，家里还有。","en":"Don't buy more, there's still some at home.","sub":"b","lv":1},{"c":"别睡了，快起床。","en":"Stop sleeping, get up quickly.","sub":"b","lv":1},{"c":"不要再买一件了。","en":"Don't buy another one.","sub":"a","lv":2},{"c":"别今天去了，明天再去吧。","en":"Don't go today, go tomorrow.","sub":"b","lv":1},{"c":"不要看我买的书了。","en":"Stop reading the book I bought.","sub":"a","lv":2},{"c":"别吃他做的菜了。","en":"Stop eating the food he cooked.","sub":"b","lv":2},{"c":"不要抽烟了。","en":"Stop smoking.","sub":"a","lv":1,"tags":["COLLOC"]},{"c":"别哭了。","en":"Don't cry.","sub":"b","lv":1,"tags":["COLLOC"]},{"c":"别吵了。","en":"Stop making noise.","sub":"b","lv":1,"tags":["COLLOC"]},{"c":"不要看他买的那个电影了。","en":"Don't watch that movie he bought any more.","sub":"a","lv":3},{"c":"别买这个手机了。","en":"Don't buy this phone any more.","sub":"b","lv":2},{"c":"别喝这个咖啡了。","en":"Don't drink this coffee any more.","sub":"b","lv":2},{"c":"别穿妈妈买的那件衣服了。","en":"Don't wear that piece of clothing Mum bought any more.","sub":"b","lv":3},{"c":"不要看他买的这个电影了。","en":"Don't watch this movie he bought any more.","sub":"a","lv":3},{"c":"别穿妈妈买的这件衣服了。","en":"Don't wear this piece of clothing Mum bought any more.","sub":"b","lv":3}]},{"id":"10-g2","no":2,"cn":"介词“对”","en":"The Preposition 对","note":"对 marks the target or recipient of an action or attitude: \"to / towards / for\".","subs":[{"id":"a","label":"S + 对 + N + V/adj","exp":"Towards someone."},{"id":"b","label":"对 + N + 有 + N","exp":"\"Be helpful / useful / good / have an influence on …\" — the noun after 有 is a small set: 帮助、好处、用、影响."},{"id":"c","label":"对 + N + 有 + 定语 + 的 + N","exp":"The noun after 有 can take an attributive: 好的影响 “a good influence”, 很大的帮助 “a lot of help”."}],"items":[{"c":"看电视对学汉语有帮助。","en":"Watching TV is helpful for learning Chinese.","sub":"b","lv":1},{"c":"他对我很好。","en":"He is very good to me.","sub":"a","lv":2},{"c":"运动对身体有好处。","en":"Exercise is good for your health.","sub":"b","lv":1},{"c":"老师对我们很好。","en":"The teacher is very good to us.","sub":"a","lv":2},{"c":"妈妈对我真好。","en":"Mum is really good to me.","sub":"a","lv":2},{"c":"他对朋友很好。","en":"He is very good to his friends.","sub":"a","lv":2},{"c":"你对我太好了。","en":"You are too good to me.","sub":"a","lv":2},{"c":"多喝水对身体有好处。","en":"Drinking more water is good for your health.","sub":"b","lv":1},{"c":"早睡早起对身体有好处。","en":"Going to bed and getting up early is good for your health.","sub":"b","lv":1},{"c":"多听多说对学汉语有帮助。","en":"Listening and speaking more helps with learning Chinese.","sub":"b","lv":1},{"c":"电脑对学习有用。","en":"Computers are useful for studying.","sub":"b","lv":1,"tags":["COLLOC"]},{"c":"看电视对休息有用。","en":"Watching TV is good for relaxing.","sub":"b","lv":1,"tags":["COLLOC"]},{"c":"学汉语对找工作有帮助。","en":"Learning Chinese helps with finding a job.","sub":"b","lv":1,"tags":["COLLOC"]},{"c":"多运动对身体健康有好处。","en":"Exercising more is good for your health.","sub":"b","lv":1,"tags":["COLLOC"]},{"c":"喝太多甜的对身体有影响。","en":"Drinking too many sweet things affects your health.","sub":"b","lv":2,"tags":["COLLOC"]},{"c":"看中文书对写中文有影响。","en":"Reading Chinese books has an influence on writing Chinese.","sub":"b","lv":1,"tags":["COLLOC"]},{"c":"吃好吃的对心情有好处。","en":"Eating tasty food is good for your mood.","sub":"b","lv":2},{"c":"睡觉对学习有好处。","en":"Sleeping is good for studying.","sub":"b","lv":1},{"c":"画画对心情有好处。","en":"Drawing is good for your mood.","sub":"b","lv":2},{"c":"见朋友对心情有好处。","en":"Seeing friends is good for your mood.","sub":"b","lv":1},{"c":"什么对心情有好处？","en":"What is good for your mood?","sub":"b","lv":1},{"c":"她的话对小妹妹们有好的影响。","en":"Her words had a good influence on the little girls.","sub":"c","lv":2,"tags":["COLLOC"]},{"c":"那个电影对孩子有坏的影响。","en":"That movie has a bad influence on children.","sub":"c","lv":2,"tags":["COLLOC"]},{"c":"老师的帮助对我有很大的影响。","en":"The teacher's help had a great influence on me.","sub":"c","lv":2,"tags":["COLLOC"]},{"c":"玩太多手机对眼睛有坏的影响。","en":"Playing on your phone too much has a bad effect on your eyes.","sub":"c","lv":2,"tags":["COLLOC"]},{"c":"妈妈的爱对孩子有好的影响。","en":"A mother's love has a good influence on children.","sub":"c","lv":2,"tags":["COLLOC"]},{"c":"你昨天说的那些话对孩子有不好的影响。","en":"What you said yesterday has a bad influence on children.","sub":"c","lv":3},{"c":"老师说的每句话对我的学习有好的影响。","en":"Everything the teacher says has a good influence on my studies.","sub":"c","lv":3},{"c":"他对我买的那台电脑很满意。","en":"He is very happy with the computer I bought.","sub":"a","lv":3},{"c":"妈妈对我做的菜很满意。","en":"Mum is very happy with the food I made.","sub":"a","lv":2},{"c":"你说的那些话对学习有帮助。","en":"What you said is helpful for studying.","sub":"b","lv":3},{"c":"老师推荐的那本书对考试有好处。","en":"That book the teacher recommended is good for the exam.","sub":"b","lv":3},{"c":"妈妈对我做的这个菜很满意。","en":"Mum is very happy with this dish I made.","sub":"a","lv":3}]},{"id":"10-g3","no":3,"cn":"形容词、副词“多”","en":"The Adjective and Adverb 多","note":"多 also means \"many / much\" as a predicate or attributive, and \"more\" as an adverb before a verb.","subs":[{"id":"a","label":"S + 多","exp":"多 as the predicate (\"there is a lot\")."},{"id":"b","label":"degree adverb + 多 + N","exp":"As an attributive (\"many …\")."},{"id":"c","label":"S + 多 + V","exp":"As an adverb (\"do more\")."},{"id":"d","label":"V + 这么多 / 那么多","exp":"这么/那么 + 多 as the object of a verb (so much / that much)."}],"items":[{"c":"人很多。","en":"There are many people.","sub":"a","lv":1},{"c":"他的头发不多。","en":"He doesn't have much hair.","sub":"a","lv":2},{"c":"题太多，我没做完。","en":"There were too many questions; I didn't finish them all.","sub":"a","lv":2},{"c":"他有很多钱。","en":"He has a lot of money.","sub":"b","lv":1},{"c":"他总有许多理由。","en":"He always has many reasons.","sub":"b","lv":1},{"c":"你怎么买了这么多东西啊？","en":"Why did you buy so many things?","sub":"b","lv":1},{"c":"你要多休息。","en":"You need to rest more.","sub":"c","lv":1},{"c":"学习汉语要多听多说。","en":"To learn Chinese you must listen and speak more.","sub":"c","lv":1},{"c":"你怎么知道这么多啊？","en":"How do you know so much?","sub":"d","lv":1},{"c":"别买那么多。","en":"Don't buy that much.","sub":"d","lv":1},{"c":"学校里的学生很多。","en":"There are many students in the school.","sub":"a","lv":2},{"c":"你的朋友真多。","en":"You have so many friends.","sub":"a","lv":2},{"c":"他买了这么多水果。","en":"He bought so much fruit.","sub":"b","lv":1},{"c":"你怎么有这么多书？","en":"How do you have so many books?","sub":"b","lv":1},{"c":"你要多运动。","en":"You should exercise more.","sub":"c","lv":1},{"c":"多吃水果，少喝咖啡。","en":"Eat more fruit and drink less coffee.","sub":"c","lv":1},{"c":"你应该多喝水。","en":"You should drink more water.","sub":"c","lv":1},{"c":"你怎么买了这么多啊？","en":"How did you buy so much?","sub":"d","lv":1},{"c":"别吃那么多。","en":"Don't eat so much.","sub":"d","lv":1},{"c":"我不知道这么多。","en":"I don't know this much.","sub":"d","lv":1},{"c":"我买的东西太多了。","en":"I bought too many things.","sub":"a","lv":3},{"c":"他说的理由太多了。","en":"He gave too many reasons.","sub":"a","lv":3},{"c":"他买了太多的书。","en":"He bought too many books.","sub":"b","lv":2},{"c":"这里有太多的车。","en":"There are too many cars here.","sub":"b","lv":2},{"c":"我买的太多的水果都坏了。","en":"Too many of the fruits I bought have gone bad.","sub":"b","lv":2},{"c":"你买的太多的书他都不看。","en":"He doesn't read any of the many books you bought.","sub":"b","lv":2},{"c":"你要多喝这个水。","en":"You should drink more of this water.","sub":"c","lv":2},{"c":"你要多穿一点儿衣服。","en":"You should wear a bit more clothing.","sub":"c","lv":2},{"c":"你要多听老师说的话。","en":"You should listen more to what the teacher says.","sub":"c","lv":2},{"c":"你买的这个书要多看几遍。","en":"You should read this book you bought a few more times.","sub":"c","lv":3},{"c":"你怎么买了这么多的书？","en":"Why did you buy so many books?","sub":"d","lv":2},{"c":"你别吃那么多的糖。","en":"Don't eat so much sugar.","sub":"d","lv":2},{"c":"你怎么买了这么多我推荐的书？","en":"Why did you buy so many of the books I recommended?","sub":"d","lv":2},{"c":"他拿了这么多我买的书。","en":"He took so many of the books I bought.","sub":"d","lv":2},{"c":"他买的那些东西里有太多的那种车。","en":"Among the things he bought there are too many of that kind of car.","sub":"b","lv":3},{"c":"他有很多我推荐的那种书。","en":"He has a lot of that kind of book I recommended.","sub":"b","lv":3},{"c":"你要多听老师说的这几句话。","en":"You should listen more to these few sentences the teacher said.","sub":"c","lv":3},{"c":"他拿了三十多本我买的书。","en":"He took more than thirty of the books I bought.","sub":"d","lv":3},{"c":"他拿了这么多我买的那种书。","en":"He took so many of that kind of book I bought.","sub":"d","lv":3}]}]},{"lesson":11,"key":"11","review":false,"title":"He is 3 years older than me","titleCn":"他比我大三岁","points":[{"id":"11-g1","no":1,"cn":"动词结构做定语","en":"Verbal Phrases as Attributives","note":"A verb phrase plus 的 can modify a noun: S + V + 的 + N.","subs":[{"id":"a","label":"S + V + 的 + N","exp":"Verbal attributive."}],"items":[{"c":"这是新买的自行车。","en":"This is a newly bought bicycle.","sub":"a","lv":1},{"c":"他是我昨天认识的朋友。","en":"He is a friend I met yesterday.","sub":"a","lv":2},{"c":"你说的话我没听懂。","en":"I didn't catch what you said.","sub":"a","lv":2},{"c":"站在门口的那个人是谁？","en":"Who is the person standing at the door?","sub":"a","lv":2},{"c":"我买的那本书很好看。","en":"The book I bought is very good.","sub":"a","lv":3},{"c":"看报纸的人很多。","en":"There are many people reading newspapers.","sub":"a","lv":2},{"c":"他做的那个蛋糕很好吃。","en":"That cake he made is delicious.","sub":"a","lv":3}]},{"id":"11-g2","no":2,"cn":"“比”字句（1）","en":"The 比 Sentence (1)","note":"The 比 sentence compares two things. The adjective is followed by 一点儿/一些/多了/得多, never by 很.","subs":[{"id":"a","label":"A + 比 + B + adj","exp":"Simple comparison."},{"id":"b","label":"A + 比 + B + adj + 一点儿/多了","exp":"Difference in degree."},{"id":"c","label":"A + 比 + B + V + 得 + complement","exp":"With a complement."}],"items":[{"c":"他比我大三岁。","en":"He is three years older than me.","sub":"a","lv":2},{"c":"今天比昨天热多了。","en":"Today is much hotter than yesterday.","sub":"b","lv":1},{"c":"他比我高一点儿。","en":"He is a little taller than me.","sub":"b","lv":2},{"c":"他比我跑得快。","en":"He runs faster than me.","sub":"c","lv":1},{"c":"他比我高。","en":"He is taller than me.","sub":"a","lv":1},{"c":"他比我喜欢读书。","en":"He likes reading more than I do.","sub":"a","lv":1},{"c":"他比我多买了一本书。","en":"He bought one more book than I did.","sub":"c","lv":2},{"c":"今天比昨天冷。","en":"Today is colder than yesterday.","sub":"a","lv":1},{"c":"这件衣服比那件贵。","en":"This piece of clothing is more expensive than that one.","sub":"a","lv":2},{"c":"这个苹果比那个大一点儿。","en":"This apple is a bit bigger than that one.","sub":"b","lv":2},{"c":"他比我高多了。","en":"He is much taller than me.","sub":"b","lv":1},{"c":"这件衣服比那件贵多了。","en":"This piece of clothing is much more expensive than that one.","sub":"b","lv":2},{"c":"我比他起得早。","en":"I get up earlier than him.","sub":"c","lv":1},{"c":"她比我唱得好。","en":"She sings better than me.","sub":"c","lv":1},{"c":"你比我说得快。","en":"You speak faster than me.","sub":"c","lv":1},{"c":"我比他大。","en":"I'm older than him.","sub":"a","lv":1},{"c":"我买的衣服比他的贵。","en":"The clothing I bought is more expensive than his.","sub":"a","lv":2},{"c":"你说的那个饭馆比这个好。","en":"The restaurant you mentioned is better than this one.","sub":"a","lv":3},{"c":"我买的手机比他的新。","en":"The phone I bought is newer than his.","sub":"a","lv":2},{"c":"我买的衣服比他的贵多了。","en":"The clothing I bought is much more expensive than his.","sub":"b","lv":2},{"c":"你说的那个饭馆比这个好一点儿。","en":"That restaurant you mentioned is a bit better than this one.","sub":"b","lv":3},{"c":"他比我多吃了一点儿饭。","en":"He ate a bit more rice than me.","sub":"c","lv":2},{"c":"我买的手机比他买的好用。","en":"The phone I bought is easier to use than the one he bought.","sub":"c","lv":2},{"c":"他做的菜比我做的香。","en":"The food he makes smells better than what I make.","sub":"c","lv":2},{"c":"我买的这个手机比他的新。","en":"This phone I bought is newer than his.","sub":"a","lv":3},{"c":"我买的这件衣服比他那件贵多了。","en":"This piece of clothing I bought is much more expensive than that one of his.","sub":"b","lv":3},{"c":"我买的这个手机比他买的好用。","en":"This phone I bought is easier to use than the one he bought.","sub":"c","lv":3},{"c":"他做的这道菜比我做的好吃。","en":"This dish he made tastes better than what I make.","sub":"c","lv":3}]},{"id":"11-g3","no":3,"cn":"助动词“可能”","en":"The Auxiliary Verb 可能","note":"可能 expresses possibility: \"probably / maybe / possibly\".","subs":[{"id":"a","label":"可能 + V/adj","exp":"It may be…"},{"id":"b","label":"可能 + 会 + V","exp":"Likely will…"}],"items":[{"c":"他可能不来了。","en":"He probably isn't coming.","sub":"a","lv":1},{"c":"明天可能会下雨。","en":"It may rain tomorrow.","sub":"b","lv":1},{"c":"他可能在家。","en":"He might be at home.","sub":"a","lv":2},{"c":"明天可能下雨。","en":"It might rain tomorrow.","sub":"a","lv":1},{"c":"他可能很忙。","en":"He might be busy.","sub":"a","lv":2},{"c":"他可能生病了。","en":"He might be sick.","sub":"a","lv":1},{"c":"他可能会来。","en":"He might come.","sub":"b","lv":1},{"c":"我可能会迟到。","en":"I might be late.","sub":"b","lv":1},{"c":"明天可能会下雪。","en":"It might snow tomorrow.","sub":"b","lv":1},{"c":"妈妈可能会生气。","en":"Mum might get angry.","sub":"b","lv":1},{"c":"他可能用我买的手机。","en":"He might be using the phone I bought.","sub":"a","lv":2},{"c":"他可能会用我买的电脑。","en":"He might use the computer I bought.","sub":"b","lv":2},{"c":"他可能很累。","en":"He is probably very tired.","sub":"a","lv":2},{"c":"他可能喜欢我买的这个包。","en":"He probably likes this bag I bought.","sub":"a","lv":3},{"c":"他可能会很忙。","en":"He will probably be very busy.","sub":"b","lv":2},{"c":"他可能会买我推荐的那本书。","en":"He will probably buy that book I recommended.","sub":"b","lv":3},{"c":"他可能用过我买的这个手机。","en":"He may have used this phone I bought.","sub":"a","lv":3},{"c":"他可能会去老师说的那个地方。","en":"He will probably go to that place the teacher mentioned.","sub":"b","lv":3},{"c":"他可能会买我推荐的那本书，因为他很喜欢。","en":"He may buy the book I recommended, since he likes it a lot.","sub":"b","lv":3},{"c":"因为最近很忙，他明天可能不去那个会议了。","en":"He may not go to that meeting tomorrow because he's been busy lately.","sub":"b","lv":3},{"c":"明天他可能会去我们上次说的那个地方，那儿很漂亮。","en":"He may go to the place we mentioned last time tomorrow — it's very pretty there.","sub":"b","lv":3}]}]},{"lesson":12,"key":"12","review":false,"title":"You wear too little","titleCn":"你穿得太少了","points":[{"id":"12-g1","no":1,"cn":"程度补语","en":"The Degree Complement","note":"A degree complement follows 得 and describes how well an action is done.","subs":[{"id":"a","label":"V + 得 + complement","exp":"Affirmative."},{"id":"b","label":"V + 得 + 不 + complement","exp":"Negative."},{"id":"c","label":"V + 得 + complement + 吗 / 不 + complement？","exp":"Questions."}],"items":[{"c":"他歌唱得好。","en":"He sings well.","sub":"a","lv":1},{"c":"他吃得多。","en":"He eats a lot.","sub":"a","lv":1},{"c":"他说得不清楚。","en":"He doesn't speak clearly.","sub":"b","lv":1},{"c":"他吃得不多。","en":"He doesn't eat much.","sub":"b","lv":1},{"c":"他住得远不远？","en":"Does he live far?","sub":"c","lv":1},{"c":"他歌唱得好吗？","en":"Does he sing well?","sub":"c","lv":1},{"c":"你走得快不快？","en":"Do you walk fast?","sub":"c","lv":1},{"c":"他跑得很快。","en":"He runs very fast.","sub":"a","lv":2},{"c":"她汉字写得很漂亮。","en":"She writes Chinese characters beautifully.","sub":"a","lv":2},{"c":"我睡得很好。","en":"I slept very well.","sub":"a","lv":2},{"c":"我睡不好。","en":"I can't sleep well.","sub":"b","lv":1},{"c":"他跑得不快。","en":"He doesn't run fast.","sub":"b","lv":1},{"c":"她写得不清楚。","en":"She doesn't write clearly.","sub":"b","lv":1},{"c":"他跑得快吗？","en":"Does he run fast?","sub":"c","lv":1},{"c":"你睡得好不好？","en":"Do you sleep well?","sub":"c","lv":1},{"c":"我买的衣服他穿得很好看。","en":"The clothing I bought looks nice on him.","sub":"a","lv":3},{"c":"他做的菜我们吃得很高兴。","en":"We enjoyed eating the food he cooked.","sub":"a","lv":3},{"c":"他跑得不太快。","en":"He doesn't run very fast.","sub":"b","lv":2},{"c":"她写得不太好。","en":"She doesn't write very well.","sub":"b","lv":2},{"c":"我买的这件衣服他穿得不太合适。","en":"The piece of clothing I bought doesn't fit him very well.","sub":"b","lv":3},{"c":"他唱的那首歌我们听得不太清楚。","en":"We couldn't hear that song he sang very clearly.","sub":"b","lv":3},{"c":"他在这家公司做得开不开心？","en":"Is he happy working at this company?","sub":"c","lv":2},{"c":"孩子们在这个学校吃得好不好？","en":"Do the children eat well at this school?","sub":"c","lv":2},{"c":"你在他说的那个学校学得好不好？","en":"Are you studying well at that school he mentioned?","sub":"c","lv":3},{"c":"你在他推荐的那家公司做得开心不开心？","en":"Are you happy working at that company he recommended?","sub":"c","lv":3},{"c":"因为那个老师讲得太快，他在那个学校学得不太好。","en":"He isn't doing well at that school because that teacher speaks too fast.","sub":"b","lv":3},{"c":"老师说的那个词他写得不太好。","en":"He doesn't write the word the teacher mentioned very well.","sub":"b","lv":3},{"c":"他唱的那首歌我们听得不太好。","en":"We couldn't hear the song he sang very well.","sub":"b","lv":3},{"c":"虽然这双鞋太贵了，你穿得舒服吗？","en":"These shoes are expensive — are they comfortable for you?","sub":"c","lv":3},{"c":"他说的那个地方很远，你们开得快不快？","en":"The place he mentioned is far — can you drive there fast?","sub":"c","lv":3},{"c":"虽然那个地方太远了，你们开得累不累？","en":"Even though that place is far, do you get tired driving?","sub":"c","lv":3}]},{"id":"12-g2","no":2,"cn":"“比”字句（2）","en":"The 比 Sentence (2)","note":"The 比 sentence also works with a degree complement: A + V + 得 + 比 + B + complement.","subs":[{"id":"a","label":"A + V + 得 + 比 + B + complement","exp":"Compares the manner of two actions."}],"items":[{"c":"她来得比我早。","en":"She came earlier than me.","sub":"a","lv":1},{"c":"他跑得比我快。","en":"He runs faster than me.","sub":"a","lv":1},{"c":"你说得比我好。","en":"You speak better than me.","sub":"a","lv":2},{"c":"我比他早到一天。","en":"I arrived one day earlier than him.","sub":"a","lv":2},{"c":"我做得比他好。","en":"I did better than him.","sub":"a","lv":1},{"c":"我买的衣服比他买的好。","en":"The clothing I bought is better than what he bought.","sub":"a","lv":2},{"c":"他做的菜比我做的好吃。","en":"The food he cooks tastes better than mine.","sub":"a","lv":2},{"c":"我买的这件衣服比他买的好。","en":"This piece of clothing I bought is better than what he bought.","sub":"a","lv":3},{"c":"他做的这道菜比我做的好吃。","en":"This dish he made tastes better than what I make.","sub":"a","lv":3}]}]},{"lesson":13,"key":"13","review":false,"title":"The door is open","titleCn":"门开着呢","points":[{"id":"13-g1","no":1,"cn":"结构助词“着”","en":"The Structural Particle 着","note":"着 marks a continuous state, or that one action is the manner of another.","subs":[{"id":"a","label":"V + 着 + (O)","exp":"Ongoing state."},{"id":"b","label":"V1 + 着 + V2","exp":"V1 is the manner of V2."}],"items":[{"c":"门开着呢。","en":"The door is open.","sub":"a","lv":1},{"c":"他穿着黑色的毛衣。","en":"He is wearing a black sweater.","sub":"a","lv":2},{"c":"大家都坐着吃饭。","en":"Everyone sits while eating.","sub":"b","lv":1},{"c":"他穿着新衣服去学校了。","en":"He went to school wearing new clothes.","sub":"b","lv":1},{"c":"窗户开着。","en":"The window is open.","sub":"a","lv":1},{"c":"他拿着一个杯子。","en":"He is holding a cup.","sub":"a","lv":2},{"c":"门上写着字。","en":"There are words written on the door.","sub":"a","lv":1},{"c":"他笑着对我说。","en":"He said to me with a smile.","sub":"b","lv":2},{"c":"大家坐着聊天。","en":"Everyone sits and chats.","sub":"b","lv":1},{"c":"她哭着回家了。","en":"She went home crying.","sub":"b","lv":1},{"c":"他穿着一件新衣服。","en":"He is wearing a new piece of clothing.","sub":"a","lv":2},{"c":"他拿着我买的书。","en":"He is holding the book I bought.","sub":"a","lv":2},{"c":"他看着我写的字笑了。","en":"He looked at the characters I wrote and smiled.","sub":"b","lv":2},{"c":"他拿着我买的那个杯子。","en":"He is holding that cup I bought.","sub":"a","lv":3},{"c":"他坐着看这本书。","en":"He sits and reads this book.","sub":"b","lv":2},{"c":"她笑着说这个事。","en":"She said this matter with a smile.","sub":"b","lv":2},{"c":"他拿着我买的花笑了。","en":"He smiled, holding the flowers I bought.","sub":"b","lv":2},{"c":"他拿着我买的这个杯子。","en":"He is holding this cup I bought.","sub":"a","lv":3},{"c":"他坐着看老师推荐的那本书。","en":"He sits reading that book the teacher recommended.","sub":"b","lv":3},{"c":"他看着我买的这个杯子笑了。","en":"He smiled, looking at this cup I bought.","sub":"b","lv":3}]},{"id":"13-g2","no":2,"cn":"反问句“不是……吗？”","en":"The Rhetorical Question 不是……吗？","note":"不是……吗？ is a rhetorical question that implies the answer is already obvious.","subs":[{"id":"a","label":"不是……吗？","exp":"\"Isn't it …?\" (obvious)"}],"items":[{"c":"你不是去北京了吗？","en":"Didn't you go to Beijing?","sub":"a","lv":1},{"c":"这不是你的书吗？","en":"Isn't this your book?","sub":"a","lv":2},{"c":"这不是你的手机吗？","en":"Isn't this your phone?","sub":"a","lv":2},{"c":"你不是喜欢她吗？","en":"Don't you like her?","sub":"a","lv":1},{"c":"你不是说好了吗？","en":"Didn't you already agree?","sub":"a","lv":2},{"c":"你不是学生吗？","en":"Aren't you a student?","sub":"a","lv":1},{"c":"你不是有两件衣服吗？","en":"Don't you have two pieces of clothing?","sub":"a","lv":2},{"c":"这不是我买的书吗？","en":"Isn't this the book I bought?","sub":"a","lv":2},{"c":"你不是说他做的菜很好吃吗？","en":"Didn't you say the food he cooks is tasty?","sub":"a","lv":3},{"c":"这不是我买的那个手机吗？","en":"Isn't this that phone I bought?","sub":"a","lv":3}]},{"id":"13-g3","no":3,"cn":"介词“往”","en":"The Preposition 往","note":"往 marks the direction towards which a movement goes: \"towards / to\".","subs":[{"id":"a","label":"往 + direction + V","exp":"Movement towards."}],"items":[{"c":"往前走。","en":"Go straight ahead.","sub":"a","lv":1},{"c":"往左拐就到了。","en":"Turn left and you'll be there.","sub":"a","lv":1},{"c":"他往学校走了。","en":"He headed towards the school.","sub":"a","lv":1},{"c":"往右走。","en":"Walk to the right.","sub":"a","lv":1},{"c":"往上看。","en":"Look up.","sub":"a","lv":1},{"c":"请您往前走一点儿。","en":"Please walk forward a bit.","sub":"a","lv":2},{"c":"你往左边走，五分钟就到。","en":"Walk to the left and you'll be there in five minutes.","sub":"a","lv":1},{"c":"他往老师说的地方走了。","en":"He walked towards the place the teacher mentioned.","sub":"a","lv":2},{"c":"他往我们昨天去过的那个公园走了。","en":"He walked towards the park we visited yesterday.","sub":"a","lv":3},{"c":"往后退两步。","en":"Take two steps back.","sub":"a","lv":1},{"c":"他往那个公园走了。","en":"He walked towards that park.","sub":"a","lv":2},{"c":"他往老师说的那个方向走了。","en":"He walked in that direction the teacher mentioned.","sub":"a","lv":3}]},{"id":"13-g4","no":4,"cn":"简单趋向补语","en":"Simple Directional Complements","note":"A directional complement follows the verb to show the direction of the action: 来 (towards the speaker) or 去 (away).","subs":[{"id":"a","label":"V + 来/去","exp":"Direction relative to the speaker."},{"id":"b","label":"V + 上/下/进/出/回/过/起 + 来/去","exp":"Compound directional complements."},{"id":"c","label":"V + 来/去 + (O)","exp":"With an object."}],"items":[{"c":"他进来了。","en":"He came in.","sub":"a","lv":1},{"c":"老师出去了。","en":"The teacher went out.","sub":"a","lv":1},{"c":"请上来。","en":"Please come up.","sub":"b","lv":1},{"c":"太阳出来了。","en":"The sun has come out.","sub":"b","lv":1},{"c":"他带来了一些水果。","en":"He brought some fruit.","sub":"c","lv":2},{"c":"我给你送去。","en":"I'll take it over to you.","sub":"c","lv":2},{"c":"他回来了。","en":"He came back.","sub":"a","lv":1},{"c":"我马上过去。","en":"I'll go over right away.","sub":"a","lv":1},{"c":"请你过来一下。","en":"Please come over.","sub":"a","lv":2},{"c":"他走出来了。","en":"He walked out.","sub":"b","lv":1},{"c":"他跑出去了。","en":"He ran out.","sub":"b","lv":1},{"c":"老师走进来了。","en":"The teacher walked in.","sub":"b","lv":1},{"c":"他拿来了一个杯子。","en":"He brought a cup.","sub":"c","lv":2},{"c":"妈妈买来了水果。","en":"Mum bought some fruit and brought it.","sub":"c","lv":1},{"c":"他带回来一本书。","en":"He brought back a book.","sub":"c","lv":2},{"c":"他带来了一本书。","en":"He brought a book.","sub":"c","lv":2},{"c":"我买的水果他都带回来了。","en":"He brought back all the fruit I bought.","sub":"c","lv":2},{"c":"老师说的那本书他买回来了。","en":"He bought back the book the teacher mentioned.","sub":"c","lv":3},{"c":"他从这个门进去了。","en":"He went in through this door.","sub":"a","lv":2},{"c":"他从我买的那个门进去了。","en":"He went in through that door I bought.","sub":"a","lv":3},{"c":"他往老师说的那个方向走过去了。","en":"He walked off towards the direction the teacher mentioned.","sub":"a","lv":3},{"c":"他走进这个房间来了。","en":"He came walking into this room.","sub":"b","lv":2},{"c":"老师走上这个楼来了。","en":"The teacher came walking up this building.","sub":"b","lv":2},{"c":"他走进我买的那个房间去了。","en":"He went walking into that room I bought.","sub":"b","lv":3},{"c":"老师走上他说的那个楼来了。","en":"The teacher came walking up that building he mentioned.","sub":"b","lv":3},{"c":"他把我买的这个杯子拿来了。","en":"He brought this cup I bought.","sub":"c","lv":3},{"c":"因为那本书很好看，他从那个商店给我买来了。","en":"Since that book is good, he bought it for me from that shop.","sub":"a","lv":3},{"c":"老师推荐的那本词典我在网上买来了。","en":"I bought the dictionary the teacher recommended online.","sub":"a","lv":3},{"c":"因为外面下雨了，老师从那个门走进来了。","en":"Since it's raining outside, the teacher came in through that door.","sub":"b","lv":3},{"c":"老师从一楼走上他说的那个楼来了。","en":"The teacher came up from the first floor to the building he mentioned.","sub":"b","lv":3}]},{"id":"13-g5","no":5,"cn":"进行态“在/正在……呢”","en":"The Progressive 在/正在……呢","note":"在 / 正在 / 正 + V + 呢 marks an action in progress. 在 is the plainest; 正在 is the most emphatic; 正 must pair with 呢.","subs":[{"id":"a","label":"S + 正在 + V + 呢","exp":"The most emphatic progressive."},{"id":"b","label":"S + 在 + V + 呢","exp":"The plain progressive."},{"id":"c","label":"S + 正 + V + 呢","exp":"正 must be followed by 呢."},{"id":"d","label":"S + V + 呢","exp":"呢 alone can mark the progressive."}],"items":[{"c":"我正在买东西呢。","en":"I am (in the middle of) shopping.","sub":"a","lv":2},{"c":"他正在准备午饭呢。","en":"He is preparing lunch right now.","sub":"a","lv":2},{"c":"你在做什么呢？","en":"What are you doing?","sub":"b","lv":2},{"c":"我在开会呢。","en":"I am in a meeting.","sub":"b","lv":2},{"c":"我正看书呢。","en":"I am reading right now.","sub":"c","lv":1},{"c":"我学习呢。","en":"I am studying.","sub":"d","lv":1},{"c":"那个正在说话的女孩儿是谁？","en":"Who is that girl who is speaking?","sub":"a","lv":2},{"c":"我正在吃饭呢。","en":"I'm eating right now.","sub":"a","lv":2},{"c":"他正在打电话呢。","en":"He's on the phone right now.","sub":"a","lv":2},{"c":"我在做饭呢。","en":"I'm cooking.","sub":"b","lv":2},{"c":"他在睡觉呢。","en":"He's sleeping.","sub":"b","lv":2},{"c":"我在写作业呢。","en":"I'm doing homework.","sub":"b","lv":2},{"c":"我正等你呢。","en":"I'm waiting for you.","sub":"c","lv":1},{"c":"他正上课呢。","en":"He's in class.","sub":"c","lv":1},{"c":"妈妈正忙呢。","en":"Mum is busy.","sub":"c","lv":1},{"c":"我正想去呢。","en":"I was just about to go.","sub":"c","lv":1},{"c":"我看电视呢。","en":"I'm watching TV.","sub":"d","lv":1},{"c":"他吃饭呢。","en":"He's eating.","sub":"d","lv":1},{"c":"我们开会呢。","en":"We're in a meeting.","sub":"d","lv":1},{"c":"她睡觉呢。","en":"She's sleeping.","sub":"d","lv":1},{"c":"我正在看一本书。","en":"I am reading a book right now.","sub":"a","lv":2},{"c":"我在等一个朋友。","en":"I am waiting for a friend.","sub":"b","lv":2},{"c":"我正在看我买的书。","en":"I am reading the book I bought right now.","sub":"a","lv":3},{"c":"他在吃我做的饭呢。","en":"He is eating the food I made.","sub":"b","lv":3},{"c":"我正在看他买的那本书。","en":"I am reading that book he bought.","sub":"a","lv":3},{"c":"我在看这个电影呢。","en":"I am watching this movie.","sub":"b","lv":2},{"c":"他在用我买的那个手机呢。","en":"He is using that phone I bought.","sub":"b","lv":3},{"c":"我正吃这个药呢。","en":"I am taking this medicine right now.","sub":"c","lv":2},{"c":"他正吃我买的那个蛋糕呢。","en":"He is eating that cake I bought.","sub":"c","lv":3},{"c":"妈妈正做她说的那个菜呢。","en":"Mum is cooking that dish she mentioned.","sub":"c","lv":3},{"c":"他吃这个药呢。","en":"He is taking this medicine.","sub":"d","lv":2},{"c":"我看那个电影呢。","en":"I am watching that movie.","sub":"d","lv":2},{"c":"他用我买的那个手机呢。","en":"He is using that phone I bought.","sub":"d","lv":3},{"c":"她穿妈妈买的那件衣服呢。","en":"She is wearing that piece of clothing Mum bought.","sub":"d","lv":3},{"c":"我正看这个电影呢。","en":"I am watching this movie right now.","sub":"c","lv":2},{"c":"因为明天要考试，我们正在那个教室复习呢。","en":"We're reviewing in that classroom because there's an exam tomorrow.","sub":"c","lv":3},{"c":"妈妈正给我做他说的那个菜呢。","en":"Mom is making the dish he mentioned for me right now.","sub":"c","lv":3},{"c":"孩子们正跟老师玩我买的那个玩具呢。","en":"The kids are playing with the toy I bought, together with the teacher.","sub":"c","lv":3},{"c":"因为他下午要交作业，现在他在教室用那个电脑写呢。","en":"He's typing on that computer in the classroom now because he must hand in homework this afternoon.","sub":"d","lv":3},{"c":"孩子们跟我买的那个小狗玩呢，很高兴。","en":"The kids are playing with the puppy I bought and are very happy.","sub":"d","lv":3}]}]},{"lesson":14,"key":"14","review":false,"title":"Have you seen that movie","titleCn":"你看过那个电影","points":[{"id":"14-g1","no":1,"cn":"结构助词“过”","en":"The Structural Particle 过","note":"过 marks that an action has been experienced before. Negate with 没（有）; 过 stays after the verb.","subs":[{"id":"a","label":"V + 过 + (O)","exp":"Experiential aspect."},{"id":"b","label":"没（有）+ V + 过","exp":"Never done."},{"id":"c","label":"V + 过 + (O) + 吗 / 没有？","exp":"Questions."}],"items":[{"c":"你看过那个电影吗？","en":"Have you seen that movie?","sub":"c","lv":2},{"c":"我吃过。","en":"I have eaten it (before).","sub":"a","lv":1},{"c":"我没去过日本。","en":"I have never been to Japan.","sub":"b","lv":1},{"c":"你看过这部电影没有？","en":"Have you seen this movie or not?","sub":"c","lv":2},{"c":"我见过他。","en":"I have met him.","sub":"a","lv":1},{"c":"他来过我们家。","en":"He has been to our house.","sub":"a","lv":1},{"c":"他去过中国没？","en":"Has he been to China or not?","sub":"c","lv":1},{"c":"你看过这部电影没？","en":"Have you seen this movie or not?","sub":"c","lv":2},{"c":"你吃过药了吗？","en":"Have you taken your medicine?","sub":"c","lv":1},{"c":"你洗过澡了吗？","en":"Have you had a shower?","sub":"c","lv":1},{"c":"我没听过。","en":"I have never heard it.","sub":"b","lv":1},{"c":"我去过北京。","en":"I've been to Beijing.","sub":"a","lv":1},{"c":"我吃过饺子。","en":"I've eaten dumplings.","sub":"a","lv":1},{"c":"我没去过上海。","en":"I've never been to Shanghai.","sub":"b","lv":1},{"c":"我没见过他。","en":"I've never seen him.","sub":"b","lv":1},{"c":"我没吃过日本菜。","en":"I've never eaten Japanese food.","sub":"b","lv":1},{"c":"我看过一本书，很有意思。","en":"I have read a book, it was very interesting.","sub":"a","lv":2},{"c":"他来过一次。","en":"He has been here once.","sub":"a","lv":2},{"c":"我去过两次北京。","en":"I've been to Beijing twice.","sub":"c","lv":2},{"c":"我去过老师推荐的那个地方。","en":"I've been to the place the teacher recommended.","sub":"a","lv":3},{"c":"我看过他写的书。","en":"I've read the book he wrote.","sub":"a","lv":2},{"c":"我去过这个公园。","en":"I have been to this park.","sub":"a","lv":2},{"c":"我没看过这个电影。","en":"I haven't seen this movie.","sub":"b","lv":2},{"c":"我没吃过这种水果。","en":"I haven't eaten this kind of fruit.","sub":"b","lv":2},{"c":"我没看过他买的那个电影。","en":"I haven't seen that movie he bought.","sub":"b","lv":3},{"c":"我没去过老师说的那个地方。","en":"I haven't been to that place the teacher mentioned.","sub":"b","lv":3},{"c":"你看过这个电影没有？","en":"Have you seen this movie?","sub":"c","lv":2},{"c":"你看过他买的那个电影没有？","en":"Have you seen that movie he bought?","sub":"c","lv":3},{"c":"你去过老师推荐的那个公园吗？","en":"Have you been to that park the teacher recommended?","sub":"c","lv":3},{"c":"我去过老师推荐的这个地方。","en":"I've been to this place the teacher recommended.","sub":"a","lv":3},{"c":"虽然我住在这儿很多年了，可是我没去过那个公园。","en":"Even though I've lived here for years, I've never been to that park.","sub":"b","lv":3},{"c":"我没吃过妈妈做的那种菜，听说很好吃。","en":"I've never eaten the kind of dish my mom makes; I hear it's delicious.","sub":"b","lv":3},{"c":"我没看过他推荐的那部电影。","en":"I've never seen the movie he recommended.","sub":"b","lv":3}]},{"id":"14-g2","no":2,"cn":"虽然……但是……","en":"虽然……但是……","note":"虽然……但是…… concedes a point and then contrasts it: \"although … but …\".","subs":[{"id":"a","label":"虽然……，但是……","exp":"Concession + contrast."},{"id":"b","label":"虽然……，可是……","exp":"可是 variant."}],"items":[{"c":"虽然很累，但是我们很开心。","en":"Although we were tired, we were very happy.","sub":"a","lv":2},{"c":"虽然下雨了，可是他还是去了。","en":"Although it rained, he still went.","sub":"b","lv":1},{"c":"虽然很贵，但是我想买。","en":"Although it's expensive, I want to buy it.","sub":"a","lv":2},{"c":"虽然很忙，但是我很开心。","en":"Although I'm busy, I'm happy.","sub":"a","lv":2},{"c":"虽然是星期天，但是我要上班。","en":"Although it's Sunday, I have to work.","sub":"a","lv":1},{"c":"虽然很远，但是我不累。","en":"Although it's far, I'm not tired.","sub":"a","lv":2},{"c":"虽然很累，可是我不想睡觉。","en":"Although I'm tired, I don't want to sleep.","sub":"b","lv":2},{"c":"虽然下雪了，可是不冷。","en":"Although it snowed, it's not cold.","sub":"b","lv":1},{"c":"虽然很近，可是我要坐车。","en":"Although it's close, I need to take the bus.","sub":"b","lv":2},{"c":"虽然迟到了，可是没关系。","en":"Although I was late, it's fine.","sub":"b","lv":1},{"c":"虽然只有两个人，但是我们很开心。","en":"Although there were only two people, we were very happy.","sub":"a","lv":2},{"c":"虽然去了一次，但是我还想去。","en":"Although I went once, I still want to go.","sub":"a","lv":2},{"c":"虽然今天很冷，可是我还是去了。","en":"Although it was cold today, I still went.","sub":"b","lv":2},{"c":"虽然他说的话很难懂，但是我还是听懂了。","en":"Although what he said was hard to understand, I understood it.","sub":"a","lv":3},{"c":"虽然我买的那件衣服很贵，可是很好看。","en":"Although the clothing I bought is expensive, it is very nice.","sub":"a","lv":3},{"c":"虽然他说的话很难，可是我听懂了。","en":"Although what he said was hard, I understood it.","sub":"b","lv":3},{"c":"虽然我买的那个手机很贵，可是很好用。","en":"Although the phone I bought was expensive, it is easy to use.","sub":"b","lv":3}]},{"id":"14-g3","no":3,"cn":"动量补语“次”","en":"The Complement of Frequency 次","note":"A complement of quantity follows the verb to give frequency or duration.","subs":[{"id":"a","label":"V + Num + 次","exp":"Frequency."},{"id":"b","label":"V + duration","exp":"Duration of an action."},{"id":"c","label":"V + 过 + Num + 次","exp":"Past frequency."}],"items":[{"c":"北京我去过两次。","en":"I have been to Beijing twice.","sub":"c","lv":1},{"c":"我去过三次长城。","en":"I have been to the Great Wall three times.","sub":"a","lv":1},{"c":"他在北京住了一天。","en":"He stayed in Beijing for one day.","sub":"b","lv":2},{"c":"这本书我看过两遍。","en":"I have read this book twice.","sub":"c","lv":2},{"c":"这个电影我看了两次。","en":"I watched this movie twice.","sub":"a","lv":2},{"c":"我给你打了两次电话。","en":"I called you twice.","sub":"a","lv":2},{"c":"我每天吃两次药。","en":"I take medicine twice a day.","sub":"a","lv":2},{"c":"他一星期来两次。","en":"He comes twice a week.","sub":"a","lv":1},{"c":"我睡了一个小时。","en":"I slept for an hour.","sub":"b","lv":1},{"c":"他等了三十分钟。","en":"He waited thirty minutes.","sub":"b","lv":1},{"c":"我们坐了一个小时飞机。","en":"We took a one-hour flight.","sub":"b","lv":1},{"c":"我学习了一个下午。","en":"I studied all afternoon.","sub":"b","lv":1},{"c":"我去过两次长城。","en":"I've been to the Great Wall twice.","sub":"c","lv":1},{"c":"我看过三遍这个电影。","en":"I've watched this movie three times.","sub":"c","lv":2},{"c":"他来过我家一次。","en":"He's been to my home once.","sub":"c","lv":1},{"c":"我吃过两次老师做的饭。","en":"I've eaten the food the teacher cooks twice.","sub":"c","lv":2},{"c":"我去过三次他说的那个地方。","en":"I've been to the place he mentioned three times.","sub":"c","lv":3},{"c":"我吃过三次妈妈做的饭。","en":"I've eaten Mum's cooking three times.","sub":"a","lv":2},{"c":"他去过两次老师说的那个地方。","en":"He's been to that place the teacher mentioned twice.","sub":"a","lv":3},{"c":"我在这个公司工作了三年。","en":"I worked at this company for three years.","sub":"b","lv":2},{"c":"我等了这个朋友一个小时。","en":"I waited for this friend for an hour.","sub":"b","lv":2},{"c":"我在他说的那个公司工作了三年。","en":"I worked at that company he mentioned for three years.","sub":"b","lv":3},{"c":"我在我买的那个房子里住了两年。","en":"I lived in that house I bought for two years.","sub":"b","lv":3},{"c":"我吃过三次妈妈做的这个菜。","en":"I've eaten this dish Mum makes three times.","sub":"a","lv":3},{"c":"我去过两次他说的这个地方。","en":"I've been to this place he mentioned twice.","sub":"c","lv":3}]}]},{"lesson":15,"key":"15","review":false,"title":"The new year is coming","titleCn":"新年就要到了","points":[{"id":"15-g1","no":1,"cn":"动作的状态“要……了”","en":"The State 要……了","note":"要……了 / 快（要）……了 / 就要……了 all signal that something is about to happen.","subs":[{"id":"a","label":"要 + V + 了","exp":"About to happen."},{"id":"b","label":"快（要）+ V + 了","exp":"Happening soon."},{"id":"c","label":"就要 + V + 了","exp":"About to (with a time word)."}],"items":[{"c":"新年就要到了。","en":"The New Year is coming soon.","sub":"c","lv":2},{"c":"要下雨了。","en":"It's going to rain.","sub":"a","lv":1},{"c":"快上课了。","en":"Class is about to start.","sub":"b","lv":1},{"c":"火车快要开了。","en":"The train is about to leave.","sub":"b","lv":2},{"c":"天要黑了。","en":"It's getting dark.","sub":"a","lv":1},{"c":"要吃饭了。","en":"It's time to eat.","sub":"a","lv":1},{"c":"我要走了。","en":"I'm about to leave.","sub":"a","lv":1},{"c":"车要开了。","en":"The bus is about to leave.","sub":"a","lv":2},{"c":"天快要下雨了。","en":"It's about to rain.","sub":"b","lv":1},{"c":"他快要回来了。","en":"He's about to come back.","sub":"b","lv":2},{"c":"我们快要到了。","en":"We're almost there.","sub":"b","lv":2},{"c":"火车就要开了。","en":"The train is about to leave.","sub":"c","lv":2},{"c":"我们就要出发了。","en":"We're about to set off.","sub":"c","lv":1},{"c":"我就要回家了。","en":"I'm about to go home.","sub":"c","lv":1},{"c":"明天就要考试了。","en":"There's an exam tomorrow.","sub":"c","lv":1},{"c":"火车十分钟就要开了。","en":"The train will leave in ten minutes.","sub":"c","lv":2},{"c":"我明天就要回国了。","en":"I'm going back to my country tomorrow.","sub":"c","lv":1},{"c":"他说的那个电影快要开始了。","en":"The movie he mentioned is about to start.","sub":"b","lv":3},{"c":"我买的书快要看完了。","en":"I'm almost finished reading the book I bought.","sub":"b","lv":3},{"c":"这个电影要开始了。","en":"This movie is about to start.","sub":"a","lv":2},{"c":"老师说的那个考试要开始了。","en":"That exam the teacher mentioned is about to start.","sub":"a","lv":3},{"c":"我买的那个手机要坏了。","en":"That phone I bought is about to break.","sub":"a","lv":3},{"c":"他说的那个电影就要开始了。","en":"That movie he mentioned is about to start.","sub":"c","lv":3},{"c":"我买的那本书就要看完了。","en":"I am about to finish that book I bought.","sub":"c","lv":3},{"c":"因为这双鞋太小了，我要去换一双。","en":"These shoes are too small, so I'm going to exchange them.","sub":"a","lv":3},{"c":"老师推荐的那本书很贵，明天要还了。","en":"The book the teacher recommended is expensive and is due back tomorrow.","sub":"a","lv":3}]},{"id":"15-g2","no":2,"cn":"副词“都”","en":"The Adverb 都","note":"都 has two uses: \"all / every one\" (things before 都), and 都……了 \"already reached a point\".","subs":[{"id":"a","label":"S + 都 + V/adj","exp":"\"All / every one\" — refers to what precedes 都."},{"id":"b","label":"都 + time/quantity + 了","exp":"Already reached a point (often with surprise)."},{"id":"c","label":"都……了，……","exp":"With a follow-up clause."}],"items":[{"c":"苹果都很大。","en":"The apples are all very big.","sub":"a","lv":2},{"c":"我们都是中国人。","en":"We are all Chinese.","sub":"a","lv":1},{"c":"孩子们都喜欢睡觉。","en":"Children all like sleeping.","sub":"a","lv":1},{"c":"都准备好了吗？","en":"Is everything ready?","sub":"a","lv":2},{"c":"都七岁了，应该去学校了。","en":"You're already seven, you should go to school.","sub":"b","lv":2},{"c":"都十一点了，怎么还不睡觉？","en":"It's already eleven — why aren't you asleep yet?","sub":"c","lv":2},{"c":"都这么多人了，怎么还不开始？","en":"There are already so many people — why haven't we started?","sub":"c","lv":1},{"c":"大家都很高兴。","en":"Everyone is happy.","sub":"a","lv":2},{"c":"都九点了。","en":"It's already nine o'clock.","sub":"b","lv":2},{"c":"都十个人了。","en":"There are already ten people.","sub":"b","lv":2},{"c":"都三个小时了。","en":"It's been three hours already.","sub":"b","lv":2},{"c":"都这么晚了。","en":"It's already so late.","sub":"b","lv":1},{"c":"都十二点了，快去睡觉吧。","en":"It's already midnight, go to bed.","sub":"c","lv":2},{"c":"都下雨了，别出去了。","en":"It's already raining, don't go out.","sub":"c","lv":1},{"c":"都吃完饭了，我们走吧。","en":"We've all finished eating, let's go.","sub":"c","lv":2},{"c":"我买的书都很好看。","en":"The books I bought are all very nice.","sub":"a","lv":3},{"c":"他做的菜我们都喜欢吃。","en":"We all like eating the food he cooks.","sub":"a","lv":2},{"c":"他到老师说的那个地方都三天了。","en":"It has been three days since he got to that place the teacher mentioned.","sub":"b","lv":3},{"c":"我买的那个手机都用两年了。","en":"I've had that phone I bought for two years already.","sub":"b","lv":3},{"c":"都到老师说的那个时间了，我们快走吧。","en":"It's already the time the teacher mentioned — let's go.","sub":"c","lv":3},{"c":"你买的那本书都看了三天了，还没看完？","en":"You've been reading that book for three days and still haven't finished?","sub":"c","lv":3},{"c":"我买的这些书都很好看。","en":"All these books I bought are very good.","sub":"a","lv":3}]}]}];
